QT_ISI(24,{"4090":["(Maka siapakah) artinya, tiada seorang pun (yang lebih aniaya daripada orang yang membuat-buat dusta terhadap Allah) dengan cara menisbatkan kepada-Nya mempunyai sekutu dan anak (dan mendustakan kebenaran) Alquran (ketika datang kepadanya. Bukankah di neraka Jahanam tersedia tempat tinggal) yakni tempat menetap (bagi orang-orang yang kafir?) tentu saja disediakan.",[["۞ فَمَنْ","Then who"],["أَظْلَمُ","(is) more unjust"],["مِمَّن","than (one) who"],["كَذَبَ","lies"],["عَلَى","against"],["ٱللَّهِ","Allah"],["وَكَذَّبَ","and denies"],["بِٱلصِّدْقِ","the truth"],["إِذْ","when"],["جَآءَهُۥٓ ۚ","it comes to him"],["أَلَيْسَ","Is (there) not"],["فِى","in"],["جَهَنَّمَ","Hell"],["مَثْوًۭى","an abode"],["لِّلْكَـٰفِرِينَ","for the disbelievers"]]],"4091":["(Dan orang yang membawa kebenaran) yaitu Nabi saw. (dan membenarkannya) orang-orang mukmin. Lafal Al-Ladzii di sini bermakna Al-Ladziina, yakni jamak (mereka itulah orang-orang yang bertakwa) maksudnya, yang menghindarkan diri dari kemusyrikan.",[["وَٱلَّذِى","And the one who"],["جَآءَ","brought"],["بِٱلصِّدْقِ","the truth"],["وَصَدَّقَ","and believed"],["بِهِۦٓ ۙ","in it"],["أُو۟لَـٰٓئِكَ","those"],["هُمُ","[they]"],["ٱلْمُتَّقُونَ","(are) the righteous"]]],"4092":["(Mereka memperoleh apa yang mereka kehendaki pada sisi Rabb mereka. Demikianlah balasan orang-orang yang berbuat baik) untuk diri mereka sendiri, berkat keimanan mereka.",[["لَهُم","For them"],["مَّا","(is) what"],["يَشَآءُونَ","they wish"],["عِندَ","with"],["رَبِّهِمْ ۚ","their Lord"],["ذَٰلِكَ","That"],["جَزَآءُ","(is the) reward"],["ٱلْمُحْسِنِينَ","(of) the good-doers"]]],"4093":["(Agar Allah menutupi mengampuni bagi mereka perbuatan buruk yang mereka kerjakan dan membalas mereka dengan upah yang baik dari apa yang telah mereka kerjakan) lafal Aswa-a dan Ahsana bermakna As-Sayyi dan Al-Hasan.",[["لِيُكَفِّرَ","That Allah will remove"],["ٱللَّهُ","That Allah will remove"],["عَنْهُمْ","from them"],["أَسْوَأَ","(the) worst"],["ٱلَّذِى","(of) what"],["عَمِلُوا۟","they did"],["وَيَجْزِيَهُمْ","and reward them"],["أَجْرَهُم","their due"],["بِأَحْسَنِ","for (the) best"],["ٱلَّذِى","(of) what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"4094":["(Bukankah Allah cukup untuk melindungi hamba-Nya) yakni Nabi saw. tentu saja, (Dan mereka mempertakuti kamu) khithab ini ditujukan kepada Nabi saw. sendiri (dengan sesembahan-sesembahan yang selain Allah) yakni, berhala-berhala; maksud mereka, bahwa berhala-berhala itu akan membunuhnya atau akan membuatnya cacat. (Dan siapa yang disesatkan Allah maka tidak seorang pun pemberi petunjuk baginya.)",[["أَلَيْسَ","Is not"],["ٱللَّهُ","Allah"],["بِكَافٍ","sufficient"],["عَبْدَهُۥ ۖ","(for) His slave"],["وَيُخَوِّفُونَكَ","And they threaten you"],["بِٱلَّذِينَ","with those"],["مِن","besides Him"],["دُونِهِۦ ۚ","besides Him"],["وَمَن","And whoever"],["يُضْلِلِ","Allah lets go astray "],["ٱللَّهُ","Allah lets go astray "],["فَمَا","then not"],["لَهُۥ","for him"],["مِنْ","any"],["هَادٍۢ","guide"]]],"4095":["(Dan barang siapa yang diberi petunjuk oleh Allah, maka tidak seorang pun yang dapat menyesatkannya. Bukankah Allah Maha Perkasa) Maha Menang atas semua perkara-Nya (lagi mempunyai pembalasan) terhadap musuh-musuh-Nya. Tentu benar.",[["وَمَن","And whoever"],["يَهْدِ","Allah guides"],["ٱللَّهُ","Allah guides"],["فَمَا","then not"],["لَهُۥ","for him"],["مِن","any"],["مُّضِلٍّ ۗ","misleader"],["أَلَيْسَ","Is not"],["ٱللَّهُ","Allah"],["بِعَزِيزٍۢ","All-Mighty"],["ذِى","All-Able of retribution"],["ٱنتِقَامٍۢ","All-Able of retribution"]]],"4096":["(Dan sungguh jika) huruf Lam bermakna qasam (kamu tanyakan kepada mereka, \"Siapakah yang menciptakan langit dan bumi?\" Niscaya mereka menjawab, \"Allah.\" Katakanlah, \"Maka terangkanlah kepadaku tentang apa yang kalian seru) yang kalian sembah (selain Allah) yakni berhala-berhala (jika Allah hendak mendatangkan kemudaratan kepadaku, apakah berhala-berhala kalian itu dapat menghilangkan kemudaratan itu) tentu saja tidak (atau jika Allah hendak memberi rahmat kepadaku, apakah mereka dapat menahan rahmat-Nya?) tentu saja tidak pula. Menurut suatu qiraat dibaca Kaasyifaati Dhurrihii dan Mumsikaati rahmatihii (Katakanlah, \"Cukuplah Allah bagiku. Kepada-Nyalah bertawakkal orang-orang yang berserah diri\") yaitu orang-orang yang percaya hanya kepada-Nya.",[["وَلَئِن","And if"],["سَأَلْتَهُم","you ask them"],["مَّنْ","who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["لَيَقُولُنَّ","Surely, they will say"],["ٱللَّهُ ۚ","Allah"],["قُلْ","Say"],["أَفَرَءَيْتُم","Then do you see"],["مَّا","what"],["تَدْعُونَ","you invoke"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["إِنْ","if"],["أَرَادَنِىَ","Allah intended for me"],["ٱللَّهُ","Allah intended for me"],["بِضُرٍّ","harm"],["هَلْ","are"],["هُنَّ","they"],["كَـٰشِفَـٰتُ","removers"],["ضُرِّهِۦٓ","(of) harm (from) Him"],["أَوْ","or"],["أَرَادَنِى","if He intended for me"],["بِرَحْمَةٍ","mercy"],["هَلْ","are"],["هُنَّ","they"],["مُمْسِكَـٰتُ","withholders"],["رَحْمَتِهِۦ ۚ","(of) His mercy"],["قُلْ","Say"],["حَسْبِىَ","Sufficient (is) Allah for me"],["ٱللَّهُ ۖ","Sufficient (is) Allah for me"],["عَلَيْهِ","upon Him"],["يَتَوَكَّلُ","put trust"],["ٱلْمُتَوَكِّلُونَ","those who trust"]]],"4097":["(Katakanlah, \"Hai kaumku, bekerjalah sesuai dengan keadaan kalian) kondisi kalian (sesungguhnya aku akan bekerja pula) sesuai dengan keadaanku (maka kelak kalian akan mengetahui)",[["قُلْ","Say"],["يَـٰقَوْمِ","O my people"],["ٱعْمَلُوا۟","Work"],["عَلَىٰ","(according) to"],["مَكَانَتِكُمْ","your position"],["إِنِّى","indeed, I am"],["عَـٰمِلٌۭ ۖ","working"],["فَسَوْفَ","then soon"],["تَعْلَمُونَ","you will know"]]],"4098":["(siapa) lafal Man adalah Isim Maushul (yang akan mendapat siksa yang menghinakannya dan lagi ditimpa) yakni ia ditimpa (oleh azab yang kekal\") yang abadi, yaitu azab neraka; dan sungguh Allah telah menghinakan mereka di dalam perang Badar.",[["مَن","(Upon) whom"],["يَأْتِيهِ","will come"],["عَذَابٌۭ","a punishment"],["يُخْزِيهِ","disgracing him"],["وَيَحِلُّ","and descends"],["عَلَيْهِ","on him"],["عَذَابٌۭ","a punishment"],["مُّقِيمٌ","everlasting"]]],"4099":["(Sesungguhnya Kami menurunkan kepadamu Alkitab untuk manusia dengan membawa kebenaran) lafal Bil haqqi berta'alluq kepada lafal Anzalnaa (siapa yang mendapat petunjuk maka untuk dirinya sendiri) yakni hidayahnya itu untuk dirinya sendiri (dan siapa yang sesat maka sesungguhnya dia semata-mata sesat buat kerugian dirinya sendiri, dan kamu sekali-kali bukanlah orang yang bertanggung jawab terhadap mereka) lalu karenanya kamu dapat memaksa mereka untuk menerima hidayah.",[["إِنَّآ","Indeed We"],["أَنزَلْنَا","We revealed"],["عَلَيْكَ","to you"],["ٱلْكِتَـٰبَ","the Book"],["لِلنَّاسِ","for [the] mankind"],["بِٱلْحَقِّ ۖ","in truth"],["فَمَنِ","So whoever"],["ٱهْتَدَىٰ","accepts guidance"],["فَلِنَفْسِهِۦ ۖ","then (it is) for his soul"],["وَمَن","and whoever"],["ضَلَّ","goes astray"],["فَإِنَّمَا","then only"],["يَضِلُّ","he strays"],["عَلَيْهَا ۖ","against his (soul)"],["وَمَآ","And not"],["أَنتَ","you"],["عَلَيْهِم","(are) over them"],["بِوَكِيلٍ","a manager"]]],"4100":["(Allah mematikan jiwa orang ketika matinya dan) memegang (jiwa orang yang belum mati di waktu tidurnya) artinya Allah memegangnya di waktu ia tidur (maka Dia tahan jiwa orang yang telah Dia tetapkan kematiannya dan melepaskan jiwa yang lain sampai waktu yang ditentukan) bagi kematiannya. Jiwa yang dilepaskan itu hanyalah dimatikan perasaannya saja, tetapi ia masih hidup, berbeda dengan jiwa yang benar-benar dimatikan. (Sesungguhnya pada yang demikian itu) pada hal-hal yang telah disebutkan itu (terdapat tanda-tanda) yang menunjukkan akan kekuasaan Allah (bagi kaum yang berpikir) maka karenanya mereka mengetahui, bahwa yang berkuasa melakukan hal tersebut berkuasa pula untuk membangkitkannya; dan orang-orang kafir Quraisy tidak memikirkan hal ini.",[["ٱللَّهُ","Allah"],["يَتَوَفَّى","takes"],["ٱلْأَنفُسَ","the souls"],["حِينَ","(at the) time"],["مَوْتِهَا","(of) their death"],["وَٱلَّتِى","and the one who"],["لَمْ","(does) not"],["تَمُتْ","die"],["فِى","in"],["مَنَامِهَا ۖ","their sleep"],["فَيُمْسِكُ","Then He keeps"],["ٱلَّتِى","the one whom"],["قَضَىٰ","He has decreed"],["عَلَيْهَا","for them"],["ٱلْمَوْتَ","the death"],["وَيُرْسِلُ","and sends"],["ٱلْأُخْرَىٰٓ","the others"],["إِلَىٰٓ","for"],["أَجَلٍۢ","a term"],["مُّسَمًّى ۚ","specified"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) signs"],["لِّقَوْمٍۢ","for a people"],["يَتَفَكَّرُونَ","who ponder"]]],"4101":["(Bahkan) tetapi (mereka mengambil selain Allah) yaitu berhala-berhala sebagai tuhan-tuhan (pemberi syafaat) di hadapan Allah nanti, menurut dugaan mereka. (Katakanlah) kepada mereka, (\"Apakah) mereka dapat memberikan syafaat (meskipun mereka tidak memiliki sesuatu pun) daripada syafaat itu dan tidak memiliki hal-hal lainnya pula (dan tidak berakal\") yakni, kalian hanya menyembah mereka tidak ada alasan lain, hal ini tentu saja tidak patut bagi kalian.",[["أَمِ","Or"],["ٱتَّخَذُوا۟","have they taken"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["شُفَعَآءَ ۚ","intercessors"],["قُلْ","Say"],["أَوَلَوْ","Even though"],["كَانُوا۟","they were"],["لَا","not"],["يَمْلِكُونَ","possessing"],["شَيْـًۭٔا","anything"],["وَلَا","and not"],["يَعْقِلُونَ","they understand"]]],"4102":["(Katakanlah, \"Hanya kepunyaan Allahlah syafaat itu semua) maksudnya, syafaat itu khusus bagi Dia, maka tiada seorang pun yang dapat memberikannya melainkan dengan seizin Dia. (Kepunyaan-Nya kerajaan langit dan bumi. Kemudian kepada-Nya pulalah kalian dikembalikan.\")",[["قُل","Say"],["لِّلَّهِ","To Allah (belongs)"],["ٱلشَّفَـٰعَةُ","the intercession"],["جَمِيعًۭا ۖ","all"],["لَّهُۥ","For Him"],["مُلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۖ","and the earth"],["ثُمَّ","Then"],["إِلَيْهِ","to Him"],["تُرْجَعُونَ","you will be returned"]]],"4103":["(Dan apabila disebutkan nama Allah semata) tanpa menyebut nama tuhan-tuhan mereka kesal) mendongkol dan anti pati (hati orang-orang yang tidak beriman kepada kehidupan akhirat, dan apabila nama-nama sembahan-sembahan selain Allah yang disebut) yakni berhala-berhala (tiba-tiba mereka bergirang hati.)",[["وَإِذَا","And when"],["ذُكِرَ","Allah is mentioned"],["ٱللَّهُ","Allah is mentioned"],["وَحْدَهُ","Alone"],["ٱشْمَأَزَّتْ","shrink with aversion"],["قُلُوبُ","(the) hearts"],["ٱلَّذِينَ","(of) those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ ۖ","in the Hereafter"],["وَإِذَا","and when"],["ذُكِرَ","are mentioned"],["ٱلَّذِينَ","those"],["مِن","besides Him"],["دُونِهِۦٓ","besides Him"],["إِذَا","behold"],["هُمْ","They"],["يَسْتَبْشِرُونَ","rejoice"]]],"4104":["(Katakanlah, \"Wahai Allah) lafal Allaahumma maknanya sama dengan Yaa Allah (Pencipta langit dan bumi) yakni yang mengadakan keduanya (Yang mengetahui barang yang gaib dan yang nyata) yakni apa-apa yang gaib dan apa-apa yang nyata dapat disaksikan (Engkaulah Yang memutuskan antara hamba-hamba-Mu tentang apa yang selalu mereka perselisihkan\") mengenai masalah agama, berilah aku petunjuk kepada yang benar dari apa yang mereka perselisihkan.",[["قُلِ","Say"],["ٱللَّهُمَّ","O Allah"],["فَاطِرَ","Creator"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["عَـٰلِمَ","Knower"],["ٱلْغَيْبِ","(of) the unseen"],["وَٱلشَّهَـٰدَةِ","and the witnessed"],["أَنتَ","You"],["تَحْكُمُ","will judge"],["بَيْنَ","between"],["عِبَادِكَ","Your slaves"],["فِى","in"],["مَا","what"],["كَانُوا۟","they used to"],["فِيهِ","therein"],["يَخْتَلِفُونَ","differ"]]],"4105":["(Dan sekiranya orang-orang yang zalim mempunyai apa yang ada di bumi semuanya dan -ada pula- sebanyak itu besertanya, niscaya mereka akan menebus dirinya dengan itu dari siksa yang buruk pada hari kiamat. Dan jelaslah) tampaklah dengan jelas (bagi mereka azab Allah yang belum pernah mereka perkirakan) yang tidak pernah mereka duga.",[["وَلَوْ","And if"],["أَنَّ","And if"],["لِلَّذِينَ","those who"],["ظَلَمُوا۟","did wrong"],["مَا","(had) whatever"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["جَمِيعًۭا","all"],["وَمِثْلَهُۥ","and (the) like of it"],["مَعَهُۥ","with it"],["لَٱفْتَدَوْا۟","they would ransom"],["بِهِۦ","with it"],["مِن","from"],["سُوٓءِ","(the) evil"],["ٱلْعَذَابِ","(of) the punishment"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) the Resurrection"],["وَبَدَا","And (will) appear"],["لَهُم","to them"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["مَا","what"],["لَمْ","not"],["يَكُونُوا۟","they had"],["يَحْتَسِبُونَ","taken into account"]]],"4106":["(Dan jelaslah bagi mereka akibat buruk dari apa yang telah mereka perbuat dan menimpa) mengenai (kepada mereka apa yang mereka dahulu selalu memperolok-olokkannya) yakni azab.",[["وَبَدَا","And will become apparent"],["لَهُمْ","to them"],["سَيِّـَٔاتُ","(the) evils"],["مَا","(of) what"],["كَسَبُوا۟","they earned"],["وَحَاقَ","and will surround"],["بِهِم","them"],["مَّا","what"],["كَانُوا۟","they used to"],["بِهِۦ","[in it]"],["يَسْتَهْزِءُونَ","mock"]]],"4107":["(Maka apabila manusia ditimpa) yang dimaksud adalah jenis manusia (bahaya ia menyeru Kami, kemudian apabila Kami berikan kepadanya) Kami anugerahkan kepadanya (nikmat) yakni pemberian nikmat (dari Kami ia berkata, \"Sesungguhnya aku diberi nikmat itu hanyalah atas sepengetahuan) dari Allah bahwasanya aku adalah orang yang pantas untuk mendapatkannya.\" Atau dengan kata lain, karena kepintaranku. (Sebenarnya itu) maksudnya, ucapan itu (adalah ujian) cobaan yang ditimpakan kepada seorang hamba (tetapi kebanyakan mereka itu tidak mengetahui) bahwasanya pemberian nikmat itu merupakan Istidraj dan ujian baginya.",[["فَإِذَا","So when"],["مَسَّ","touches"],["ٱلْإِنسَـٰنَ","[the] man"],["ضُرٌّۭ","adversity"],["دَعَانَا","he calls upon Us"],["ثُمَّ","then"],["إِذَا","when"],["خَوَّلْنَـٰهُ","We bestow (on) him"],["نِعْمَةًۭ","a favor"],["مِّنَّا","from Us"],["قَالَ","he says"],["إِنَّمَآ","Only"],["أُوتِيتُهُۥ","I have been given it"],["عَلَىٰ","for"],["عِلْمٍۭ ۚ","knowledge"],["بَلْ","Nay"],["هِىَ","it"],["فِتْنَةٌۭ","(is) a trial"],["وَلَـٰكِنَّ","but"],["أَكْثَرَهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"4108":["(Sungguh orang-orang yang sebelum mereka juga mengatakan itu pula) yakni umat-umat sebelum mereka, seperti apa yang telah dikatakan oleh Qarun dan kaumnya yang mengatakan hal yang serupa (maka tiadalah berguna bagi mereka apa yang dahulu mereka usahakan.)",[["قَدْ","Indeed"],["قَالَهَا","said it"],["ٱلَّذِينَ","those"],["مِن","before them"],["قَبْلِهِمْ","before them"],["فَمَآ","but (did) not"],["أَغْنَىٰ","avail"],["عَنْهُم","them"],["مَّا","what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"4109":["(Maka mereka ditimpa oleh akibat buruk dari apa yang mereka usahakan) yakni menerima pembalasannya. (Dan orang-orang yang lalim di antara mereka) yakni orang-orang Quraisy (akan ditimpa akibat buruk dari usahanya dan mereka tidak dapat melepaskan diri) dari azab Kami; maka Kami timpakan kepada mereka paceklik selama tujuh tahun, sesudah itu mereka dimudahkan lagi rezekinya.",[["فَأَصَابَهُمْ","Then struck them"],["سَيِّـَٔاتُ","(the) evils"],["مَا","(of) what"],["كَسَبُوا۟ ۚ","they earned"],["وَٱلَّذِينَ","And those who"],["ظَلَمُوا۟","have wronged"],["مِنْ","of"],["هَـٰٓؤُلَآءِ","these"],["سَيُصِيبُهُمْ","will strike them"],["سَيِّـَٔاتُ","(the) evils"],["مَا","(of) what"],["كَسَبُوا۟","they earned"],["وَمَا","and not"],["هُم","they"],["بِمُعْجِزِينَ","will be able to escape"]]],"4110":["(Dan tidakkah mereka mengetahui bahwa Allah melapangkan rezeki) meluaskannya (bagi siapa yang dikehendaki-Nya) sebagai ujian baginya (dan menyempitkannya?) membatasinya bagi siapa yang dikehendaki-Nya sebagai cobaan baginya. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang beriman) kepada-Nya.",[["أَوَلَمْ","Do not"],["يَعْلَمُوٓا۟","they know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["يَبْسُطُ","extends"],["ٱلرِّزْقَ","the provision"],["لِمَن","for whom"],["يَشَآءُ","He wills"],["وَيَقْدِرُ ۚ","and restricts"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) signs"],["لِّقَوْمٍۢ","for a people"],["يُؤْمِنُونَ","who believe"]]],"4111":["(Katakanlah, \"Hai hamba-hamba-Ku yang melampaui batas terhadap diri mereka sendiri, janganlah kalian berputus asa) dapat dibaca Laa Taqnithuu atau Laa Taqnathuu; sebagian ahli qiraat ada yang membacanya Laa Taqnuthuu; artinya janganlah kalian putus asa (dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya) bagi orang yang bertobat dari kemusyrikan. (Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.)",[["۞ قُلْ","Say"],["يَـٰعِبَادِىَ","O My slaves"],["ٱلَّذِينَ","Those who"],["أَسْرَفُوا۟","have transgressed"],["عَلَىٰٓ","against"],["أَنفُسِهِمْ","themselves"],["لَا","(do) not"],["تَقْنَطُوا۟","despair"],["مِن","of"],["رَّحْمَةِ","(the) Mercy"],["ٱللَّهِ ۚ","(of) Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَغْفِرُ","forgives"],["ٱلذُّنُوبَ","the sins"],["جَمِيعًا ۚ","all"],["إِنَّهُۥ","Indeed He"],["هُوَ","He"],["ٱلْغَفُورُ","(is) the Oft-Forgiving"],["ٱلرَّحِيمُ","the Most Merciful"]]],"4112":["(Dan kembalilah kalian) bertobatlah kalian (kepada Rabb kalian, dan berserah dirilah) ikhlaskanlah di dalam beramal (kepada-Nya sebelum datang kepada kalian azab kemudian kalian tidak dapat ditolong lagi) yakni azab itu tidak dapat dicegah jika kalian tidak bertobat kepada-Nya.",[["وَأَنِيبُوٓا۟","And turn"],["إِلَىٰ","to"],["رَبِّكُمْ","your Lord"],["وَأَسْلِمُوا۟","and submit"],["لَهُۥ","to Him"],["مِن","before"],["قَبْلِ","before"],["أَن","[that]"],["يَأْتِيَكُمُ","comes to you"],["ٱلْعَذَابُ","the punishment"],["ثُمَّ","then"],["لَا","not"],["تُنصَرُونَ","you will be helped"]]],"4113":["(Dan ikutilah sebaik-baik apa yang diturunkan kepada kalian dari Rabb kalian) yaitu Alquran (sebelum datang azab kepada kalian dengan tiba-tiba, sedang kalian tidak menyadari) akan kedatangannya.",[["وَٱتَّبِعُوٓا۟","And follow"],["أَحْسَنَ","(the) best"],["مَآ","(of) what"],["أُنزِلَ","is revealed"],["إِلَيْكُم","to you"],["مِّن","from"],["رَّبِّكُم","your Lord"],["مِّن","before"],["قَبْلِ","before"],["أَن","[that]"],["يَأْتِيَكُمُ","comes to you"],["ٱلْعَذَابُ","the punishment"],["بَغْتَةًۭ","suddenly"],["وَأَنتُمْ","while you"],["لَا","(do) not"],["تَشْعُرُونَ","perceive"]]],"4114":["Maka bersegeralah kalian sebelum tiba waktunya (seseorang mengatakan, \"Alangkah menyesalnya aku) lafal Yaa Hasrataa pada asalnya adalah Yaa Hasratii, artinya amat menyesallah aku (atas kelalaianku terhadap Allah) yaitu karena tidak taat kepada-Nya (dan sesungguhnya) lafal In adalah bentuk Takhfif dari Inna, asalnya Innii yakni sesungguhnya aku (aku adalah termasuk orang-orang yang benar-benar memperolok-olokan\") agama-Nya dan Kitab-Nya.",[["أَن","Lest"],["تَقُولَ","should say"],["نَفْسٌۭ","a soul"],["يَـٰحَسْرَتَىٰ","Oh! My regret"],["عَلَىٰ","over"],["مَا","what"],["فَرَّطتُ","I neglected"],["فِى","in"],["جَنۢبِ","regard (to)"],["ٱللَّهِ","Allah"],["وَإِن","and that"],["كُنتُ","I was"],["لَمِنَ","surely, among"],["ٱلسَّـٰخِرِينَ","the mockers"]]],"4115":["(Atau datang saatnya seseorang berkata, \"Kalau sekiranya Allah memberi petunjuk kepadaku) untuk mengerjakan ketaatan sehingga aku mendapat petunjuk (tentulah aku termasuk orang-orang yang bertakwa\") yakni orang-orang yang takut akan azab-Nya.",[["أَوْ","Or"],["تَقُولَ","it should say"],["لَوْ","If that"],["أَنَّ","If that"],["ٱللَّهَ","Allah"],["هَدَىٰنِى","(had) guided me"],["لَكُنتُ","surely, I (would) have been"],["مِنَ","among"],["ٱلْمُتَّقِينَ","the righteous"]]],"4116":["(Atau datang saatnya seseorang berkata ketika ia melihat azab, \"Kalau sekiranya aku dapat kembali) ke dunia (niscaya aku akan termasuk orang-orang yang berbuat baik.\") yakni, orang-orang yang beriman. Maka, dikatakan kepada mereka oleh Allah swt.:",[["أَوْ","Or"],["تَقُولَ","it should say"],["حِينَ","when"],["تَرَى","it sees"],["ٱلْعَذَابَ","the punishment"],["لَوْ","If"],["أَنَّ","only"],["لِى","for me"],["كَرَّةًۭ","another chance"],["فَأَكُونَ","then I could be"],["مِنَ","among"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"4117":["(\"Benar, sesungguhnya telah datang ayat-ayat-Ku kepadamu) yakni, Alquran yang dapat memberikan hidayah kepadamu (lalu kamu mendustakannya dan kamu menyombongkan diri) yaitu tidak mau beriman kepada ayat-ayat-Ku (dan adalah kamu termasuk orang-orang yang kafir.\")",[["بَلَىٰ","Yes"],["قَدْ","verily"],["جَآءَتْكَ","came to you"],["ءَايَـٰتِى","My Verses"],["فَكَذَّبْتَ","but you denied"],["بِهَا","them"],["وَٱسْتَكْبَرْتَ","and were arrogant"],["وَكُنتَ","and you were"],["مِنَ","among"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"4118":["(Dan pada hari kiamat kamu akan melihat orang-orang yang berbuat dusta terhadap Allah) yaitu mereka yang menisbatkan sekutu dan anak kepada-Nya (mukanya menjadi hitam. Bukankah dalam neraka Jahanam itu ada tempat) yakni tempat tinggal (bagi orang-orang yang menyombongkan diri?) artinya, tidak mau beriman; memang benar.",[["وَيَوْمَ","And (on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["تَرَى","you will see"],["ٱلَّذِينَ","those who"],["كَذَبُوا۟","lied"],["عَلَى","about"],["ٱللَّهِ","Allah"],["وُجُوهُهُم","their faces"],["مُّسْوَدَّةٌ ۚ","(will be) blackened"],["أَلَيْسَ","Is (there) not"],["فِى","in"],["جَهَنَّمَ","Hell"],["مَثْوًۭى","an abode"],["لِّلْمُتَكَبِّرِينَ","for the arrogant"]]],"4119":["(Dan Allah menyelamatkan) dari neraka Jahanam (orang-orang yang bertakwa) orang-orang yang memelihara diri dari kemusyrikan (karena kemenangan mereka) karena mereka memperoleh tempat kemenangan, yaitu surga yang menjadi tempat tinggal mereka (mereka tidak disentuh oleh keburukan dan tidak pula mereka berduka cita.)",[["وَيُنَجِّى","And Allah will deliver"],["ٱللَّهُ","And Allah will deliver"],["ٱلَّذِينَ","those who"],["ٱتَّقَوْا۟","feared (Him)"],["بِمَفَازَتِهِمْ","to their place of salvation"],["لَا","not"],["يَمَسُّهُمُ","will touch them"],["ٱلسُّوٓءُ","the evil"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"4120":["(Allah menciptakan segala sesuatu dan Dia memelihara segala sesuatu) Dia mengatur dan menguasainya menurut apa yang dikehendaki-Nya.",[["ٱللَّهُ","Allah"],["خَـٰلِقُ","(is the) Creator"],["كُلِّ","(of) all"],["شَىْءٍۢ ۖ","things"],["وَهُوَ","and He"],["عَلَىٰ","(is) over"],["كُلِّ","all"],["شَىْءٍۢ","things"],["وَكِيلٌۭ","a Guardian"]]],"4121":["(Kepunyaan-Nyalah kunci-kunci perbendaharaan langit dan bumi) yakni berupa air hujan tumbuh-tumbuhan dan lain sebagainya (Dan orang-orang yang kafir terhadap ayat-ayat Allah) yaitu Alquran (mereka itulah orang-orang yang merugi) ayat ini berhubungan langsung dengan firman-Nya, \"Dan Allah menyelamatkan orang-orang yang bertakwa...\" (Q.S. Az-Zumar, 61) dan ayat yang ada di antara keduanya merupakan jumlah I'tiradh atau kalimat sisipan.",[["لَّهُۥ","For Him"],["مَقَالِيدُ","(are the) keys"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۗ","and the earth"],["وَٱلَّذِينَ","And those who"],["كَفَرُوا۟","disbelieve"],["بِـَٔايَـٰتِ","in (the) Verses"],["ٱللَّهِ","(of) Allah"],["أُو۟لَـٰٓئِكَ","those "],["هُمُ","they"],["ٱلْخَـٰسِرُونَ","(are) the losers"]]],"4122":["(Katakanlah, \"Maka apakah kalian menyuruh aku menyembah selain Allah, hai orang-orang yang tidak berpengetahuan?\") lafal Ghaira dinashabkan oleh lafal A'budu yang juga menjadi Ma'mul dari lafal Ta-muruunnii atau Ta-muruunanii dengan memperkirakan adanya huruf An sebelumnya.",[["قُلْ","Say"],["أَفَغَيْرَ","Is (it) other than"],["ٱللَّهِ","Allah"],["تَأْمُرُوٓنِّىٓ","you order me"],["أَعْبُدُ","(to) worship"],["أَيُّهَا","O"],["ٱلْجَـٰهِلُونَ","ignorant ones"]]],"4123":["(Dan sesungguhnya telah diwahyukan kepadamu dan kepada nabi-nabi sebelummu) demi Allah (\"Jika kamu mempersekutukan Allah) hai Muhammad, seumpamanya (niscaya akan hapuslah amalmu dan tentulah kamu termasuk orang-orang yang merugi.)",[["وَلَقَدْ","And verily"],["أُوحِىَ","it has been revealed"],["إِلَيْكَ","to you"],["وَإِلَى","and to"],["ٱلَّذِينَ","those who"],["مِن","(were) before you"],["قَبْلِكَ","(were) before you"],["لَئِنْ","if"],["أَشْرَكْتَ","you associate (with Allah)"],["لَيَحْبَطَنَّ","surely, will become worthless"],["عَمَلُكَ","your deeds"],["وَلَتَكُونَنَّ","and you will surely be"],["مِنَ","among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"4124":["(Karena itu, maka hendaklah Allah) saja (kamu sembah dan hendaklah kamu termasuk orang-orang yang bersyukur\") atas nikmat-Nya kepadamu.",[["بَلِ","Nay"],["ٱللَّهَ","But worship Allah"],["فَٱعْبُدْ","But worship Allah"],["وَكُن","and be"],["مِّنَ","among"],["ٱلشَّـٰكِرِينَ","the thankful ones"]]],"4125":["(Dan mereka tidak mengagungkan Allah dengan pengagungan yang semestinya) yakni mereka tidak mengenal Allah dengan pengenalan yang sebenarnya; atau, mereka tidak mengagungkan-Nya dengan pengagungan yang sesungguhnya sewaktu mereka menyekutukan-Nya dengan selain-Nya (padahal bumi seluruhnya) lafal ayat ini menjadi Hal dan maksud dari lafal Jamii'an ialah bumi yang berlapis tujuh itu (dalam genggaman kekuasaan-Nya) maksudnya berada di dalam kekuasaan dan tasharuf-Nya (pada hari kiamat dan langit digulung) dilipat menjadi satu (dengan tangan kanan-Nya) yakni dengan kekuasaan-Nya (Maha Suci dan Maha Tinggi Allah dari apa yang mereka persekutukan) bersama-Nya.",[["وَمَا","And not"],["قَدَرُوا۟","they appraised"],["ٱللَّهَ","Allah"],["حَقَّ","(with) true"],["قَدْرِهِۦ","appraisal"],["وَٱلْأَرْضُ","while the earth"],["جَمِيعًۭا","entirely"],["قَبْضَتُهُۥ","(will be) in His Grip"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["وَٱلسَّمَـٰوَٰتُ","and the heavens"],["مَطْوِيَّـٰتٌۢ","(will be) folded"],["بِيَمِينِهِۦ ۚ","in His Right Hand"],["سُبْحَـٰنَهُۥ","Glory be to Him"],["وَتَعَـٰلَىٰ","And High is He"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate (with Him)"]]],"4126":["(Dan ditiuplah sangkakala) pada tiupan yang pertama (maka matilah) artinya mati mendadaklah (siapa yang di langit dan di bumi kecuali siapa yang dikehendaki Allah) yaitu para bidadari, para pelayan surga dan selain keduanya. (Kemudian ditiup sangkakala itu sekali lagi maka tiba-tiba mereka) yakni semua makhluk yang telah mati itu (berdiri seraya menunggu) apa yang bakal diputuskan terhadap diri mereka.",[["وَنُفِخَ","And (will) be blown"],["فِى","[in]"],["ٱلصُّورِ","the trumpet"],["فَصَعِقَ","then (will) fall dead"],["مَن","whoever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَن","and whoever"],["فِى","(is) on"],["ٱلْأَرْضِ","the earth"],["إِلَّا","except"],["مَن","whom"],["شَآءَ","Allah wills"],["ٱللَّهُ ۖ","Allah wills"],["ثُمَّ","Then"],["نُفِخَ","(it will) be blown"],["فِيهِ","[in it]"],["أُخْرَىٰ","a second time"],["فَإِذَا","and behold"],["هُمْ","They"],["قِيَامٌۭ","(will be) standing"],["يَنظُرُونَ","waiting"]]],"4127":["(Dan terang-benderanglah bumi) menjadi terang benderanglah ia (dengan Nur Rabbnya) sewaktu Dia menampilkan kekuasaan-Nya untuk memutuskan perkara peradilan di antara makhluk-Nya (dan diberikanlah kitab) yakni buku catatan amal perbuatan untuk menjalani perhitungan (dan didatangkanlah para nabi dan saksi-saksi) yaitu Nabi Muhammad saw. dan umatnya untuk memberikan persaksian, bahwa para rasul benar-benar telah menyampaikan risalah-Nya (dan diberi keputusan di antara mereka dengan hak) yakni secara adil (sedangkan mereka tidak dirugikan) barang sedikit pun.",[["وَأَشْرَقَتِ","And (will) shine"],["ٱلْأَرْضُ","the earth"],["بِنُورِ","with (the) light"],["رَبِّهَا","(of) its Lord"],["وَوُضِعَ","and (will) be placed"],["ٱلْكِتَـٰبُ","the Record"],["وَجِا۟ىٓءَ","and (will) be brought"],["بِٱلنَّبِيِّـۧنَ","the Prophets"],["وَٱلشُّهَدَآءِ","and the witnesses"],["وَقُضِىَ","and it (will) be judged"],["بَيْنَهُم","between them"],["بِٱلْحَقِّ","in truth"],["وَهُمْ","and they"],["لَا","will not be wronged"],["يُظْلَمُونَ","will not be wronged"]]],"4128":["(Dan disempurnakan bagi tiap-tiap jiwa apa yang telah dikerjakannya) yakni balasannya (dan Dia lebih mengetahui) (apa yang mereka kerjakan) maka Dia tidak membutuhkan saksi lagi.",[["وَوُفِّيَتْ","And (will) be paid in full"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["مَّا","what"],["عَمِلَتْ","it did"],["وَهُوَ","and He"],["أَعْلَمُ","(is the) Best-Knower"],["بِمَا","of what"],["يَفْعَلُونَ","they do"]]],"4129":["(Dan orang-orang kafir dibawa) dengan secara keras dan paksa (ke neraka Jahanam berombong-rombongan) secara bergelombang lagi terpisah-pisah. (Sehingga apabila mereka sampai ke neraka itu dibukakanlah pintu-pintunya) ayat ini menjadi Jawab dari lafal Idzaa (dan berkatalah kepada mereka penjaga-penjaganya, \"Apakah belum pernah datang kepada kalian rasul-rasul di antara kalian yang membacakan kepada kalian ayat-ayat Rabb kalian) yakni Alquran dan kitab-kitab lainnya (dan memperingatkan kepada kalian akan pertemuan dengan hari ini?\" Mereka menjawab, \"Benar telah datang.\" Tetapi telah pasti berlaku ketetapan azab) yakni sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Sesungguhnya akan Aku penuhi neraka Jahanam...\" (Q.S. As-Sajdah, 13) (terhadap orang-orang yang kafir).",[["وَسِيقَ","And (will) be driven"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieve"],["إِلَىٰ","to"],["جَهَنَّمَ","Hell"],["زُمَرًا ۖ","(in) groups"],["حَتَّىٰٓ","until"],["إِذَا","when"],["جَآءُوهَا","they reach it"],["فُتِحَتْ","(will) be opened"],["أَبْوَٰبُهَا","its gates"],["وَقَالَ","and (will) say"],["لَهُمْ","to them"],["خَزَنَتُهَآ","its keepers"],["أَلَمْ","Did not"],["يَأْتِكُمْ","come to you"],["رُسُلٌۭ","Messengers"],["مِّنكُمْ","from you"],["يَتْلُونَ","reciting"],["عَلَيْكُمْ","to you"],["ءَايَـٰتِ","(the) Verses"],["رَبِّكُمْ","(of) your Lord"],["وَيُنذِرُونَكُمْ","and warning you"],["لِقَآءَ","(of the) meeting"],["يَوْمِكُمْ","(of) your Day"],["هَـٰذَا ۚ","this"],["قَالُوا۟","They (will) say"],["بَلَىٰ","Yes"],["وَلَـٰكِنْ","But"],["حَقَّتْ","has been justified"],["كَلِمَةُ","(the) word"],["ٱلْعَذَابِ","(of) punishment"],["عَلَى","against"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"4130":["(Dikatakan kepada mereka, \"Masukilah pintu-pintu Jahanam itu, sedangkan kalian kekal di dalamnya\") yakni kalian telah ditetapkan untuk menjadi penghuni yang abadi. (Maka seburuk-buruk tempat) maksudnya, tempat tinggal (orang-orang yang menyombongkan diri) adalah Jahanam.",[["قِيلَ","It will be said"],["ٱدْخُلُوٓا۟","Enter"],["أَبْوَٰبَ","(the) gates"],["جَهَنَّمَ","(of) Hell"],["خَـٰلِدِينَ","(to) abide eternally"],["فِيهَا ۖ","therein"],["فَبِئْسَ","and wretched is"],["مَثْوَى","(the) abode"],["ٱلْمُتَكَبِّرِينَ","(of) the arrogant"]]],"4131":["(Dan orang-orang yang bertakwa kepada Rabbnya dibawa) dengan lemah lembut (ke dalam surga berombong-rombongan pula, sehingga apabila mereka sampai ke surga itu pintu-pintunya telah dibuka) huruf Wau dalam ayat ini menunjukkan makna Hal dengan diperkirakan adanya lafal Qad sesudahnya (dan berkatalah kepada mereka penjaga-penjaganya, \"Kesejahteraan atas kalian, berbahagialah kalian) lafal Thibtum menjadi Hal (maka masukilah surga ini, sedangkan kalian kekal di dalamnya\") telah ditetapkan untuk menjadi penghuni yang abadi di dalamnya. Jawab lafal Idzaa diperkirakan keberadaannya, yakni lalu mereka memasukinya. Dan dibawanya orang-orang yang bertakwa ke dalam surga serta dibukakannya pintu-pintu surga sebelum mereka datang, hal ini sebagai penghormatan buat mereka. Sedangkan digiringnya orang-orang kafir serta dibukakannya pintu-pintu neraka Jahanam sewaktu mereka datang dimaksud sebagai hinaan buat mereka agar panas neraka Jahanam itu dapat dirasakan oleh mereka sebelum memasukinya",[["وَسِيقَ","And (will) be driven"],["ٱلَّذِينَ","those who"],["ٱتَّقَوْا۟","feared"],["رَبَّهُمْ","their Lord"],["إِلَى","to"],["ٱلْجَنَّةِ","Paradise"],["زُمَرًا ۖ","(in) groups"],["حَتَّىٰٓ","until"],["إِذَا","when"],["جَآءُوهَا","they reach it"],["وَفُتِحَتْ","and (will) be opened"],["أَبْوَٰبُهَا","its gates"],["وَقَالَ","and (will) say"],["لَهُمْ","to them"],["خَزَنَتُهَا","its keepers"],["سَلَـٰمٌ","Peace be"],["عَلَيْكُمْ","upon you"],["طِبْتُمْ","you have done well"],["فَٱدْخُلُوهَا","so enter it"],["خَـٰلِدِينَ","(to) abide eternally"]]],"4132":["(Dan mereka mengucapkan) sewaktu mereka memasukinya; lafal ayat ini diathafkan kepada lafal Dukhuuluhaa yang diperkirakan keberadaannya tadi pada ayat sebelumnya, (\"Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami) yakni memasukkan kami ke dalam surga (dan telah memberikan kepada kami tempat ini) surga ini (sedangkan kami diperkenankan menempati) menghuni (tempat dalam surga di mana saja kami kehendaki) karena surga itu semuanya bukanlah tempat yang dipilih antara yang satu dengan yang lainnya, karena semuanya indah (maka sebaik-baik balasan bagi orang-orang yang beramal) adalah surga.",[["وَقَالُوا۟","And they will say"],["ٱلْحَمْدُ","All praise"],["لِلَّهِ","(be) to Allah"],["ٱلَّذِى","Who"],["صَدَقَنَا","has fulfilled for us"],["وَعْدَهُۥ","His promise"],["وَأَوْرَثَنَا","and has made us inherit"],["ٱلْأَرْضَ","the earth"],["نَتَبَوَّأُ","we may settle"],["مِنَ","[from]"],["ٱلْجَنَّةِ","(in) Paradise"],["حَيْثُ","wherever"],["نَشَآءُ ۖ","we wish"],["فَنِعْمَ","So excellent"],["أَجْرُ","(is the) reward"],["ٱلْعَـٰمِلِينَ","(of) the workers"]]],"4133":["(Dan kamu akan melihat malaikat-malaikat berlingkar) lafal Haaffiina ini menjadi Hal (di sekeliling 'Arasy) yakni dari segala penjurunya (bertasbih) menjadi Hal dari dhamir Haaffiina (seraya memuji Rabb mereka) yaitu sambil mengucapkan kalimah, Subhaanallaah Wa Bihamdihi, artinya, Maha Suci Allah dan Kami memuji kepada-Nya (dan diberi putusan di antara mereka) di antara semua makhluk (dengan hak) dengan adil, maka orang-orang yang beriman dimasukkan ke dalam surga, dan orang-orang kafir dimasukkan ke dalam neraka (dan diucapkan, \"Segala puji bagi Allah, Rabb semesta alam.\") yaitu setelah kedua golongan itu telah selesai pemutusannya, lalu para malaikat mengakhirinya dengan memuji kepada Allah.",[["وَتَرَى","And you will see"],["ٱلْمَلَـٰٓئِكَةَ","the Angels"],["حَآفِّينَ","surrounding"],["مِنْ","[from]"],["حَوْلِ","around"],["ٱلْعَرْشِ","the Throne"],["يُسَبِّحُونَ","glorifying"],["بِحَمْدِ","(the) praise"],["رَبِّهِمْ ۖ","(of) their Lord"],["وَقُضِىَ","And (will) be judged"],["بَيْنَهُم","between them"],["بِٱلْحَقِّ","in truth"],["وَقِيلَ","and it will be said"],["ٱلْحَمْدُ","All praise be"],["لِلَّهِ","to Allah"],["رَبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"4134":["(Haa Miim) hanya Allah saja yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Meem"]]],"4135":["(Diturunkan Kitab ini) yakni Alquran, menjadi Mubtada (dari Allah) Khabar Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["تَنزِيلُ","(The) revelation"],["ٱلْكِتَـٰبِ","(of) the Book"],["مِنَ","(is) from"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْعَلِيمِ","the All-Knower"]]],"4136":["(Yang mengampuni dosa) orang-orang mukmin (dan menerima tobat) mereka (lagi keras hukuman-Nya) terhadap orang-orang kafir, yaitu Dia mengeraskan azab-Nya terhadap mereka (Yang mempunyai karunia) yakni Pemberi nikmat yang lapang; Dia bersifat demikian selama-lamanya. Dimudhafkannya lafal Ghaafir kepada Adz-Dzanbi, lafal Qaabil kepada At-Taubi, dan lafal Syadiid kepada Al-Iqaabi mengandung makna Takrif sebagaimana lafal terakhir yaitu Dzith Thauli. (Tiada Tuhan selain Dia. Hanya kepada-Nyalah kembali) semua makhluk pasti kembali kepada-Nya.",[["غَافِرِ","(The) Forgiver"],["ٱلذَّنۢبِ","(of) the sin"],["وَقَابِلِ","and (the) Acceptor"],["ٱلتَّوْبِ","(of) [the] repentance"],["شَدِيدِ","severe"],["ٱلْعِقَابِ","(in) the punishment"],["ذِى","Owner (of) the abundance"],["ٱلطَّوْلِ ۖ","Owner (of) the abundance"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","Him"],["إِلَيْهِ","to Him"],["ٱلْمَصِيرُ","(is) the final return"]]],"4137":["(Tidak ada yang memperdebatkan tentang ayat-ayat Allah) yakni Alquran (kecuali orang-orang yang kafir) dari kalangan penduduk kota Mekah. (Karena itu janganlah mereka pulang-balik dengan bebas dari suatu kota ke kota yang lain memperdayakan kamu) mereka pulang balik untuk mencari penghidupan dalam keadaan selamat, janganlah hal itu membuatmu teperdaya, karena sesungguhnya akibat dan tempat kembali mereka adalah neraka.",[["مَا","Not"],["يُجَـٰدِلُ","dispute"],["فِىٓ","concerning"],["ءَايَـٰتِ","(the) Verses"],["ٱللَّهِ","(of) Allah"],["إِلَّا","except"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["فَلَا","so (let) not"],["يَغْرُرْكَ","deceive you"],["تَقَلُّبُهُمْ","their movement"],["فِى","in"],["ٱلْبِلَـٰدِ","the cities"]]],"4138":["(Sebelum mereka, kaum Nuh dan golongan-golongan yang bersekutu telah mendustakan) rasul-rasulnya, seperti Ad dan Tsamud serta kaum-kaum lainnya (sesudah mereka, dan tiap-tiap umat telah merencanakan makar terhadap rasul mereka untuk menawannya) untuk membunuhnya (dan mereka membantah dengan alasan yang batil untuk melenyapkan) untuk menghapuskan (kebenaran dengan yang batil itu; karena itu Aku azab mereka) dengan siksaan. (Maka betapa pedihnya azab-Ku) terhadap mereka; hal itu sesuai dengan imbalan yang harus mereka terima.",[["كَذَّبَتْ","Denied"],["قَبْلَهُمْ","before them"],["قَوْمُ","(the) people"],["نُوحٍۢ","(of) Nuh"],["وَٱلْأَحْزَابُ","and the factions"],["مِنۢ","after them"],["بَعْدِهِمْ ۖ","after them"],["وَهَمَّتْ","and plotted"],["كُلُّ","every"],["أُمَّةٍۭ","nation"],["بِرَسُولِهِمْ","against their Messenger"],["لِيَأْخُذُوهُ ۖ","to seize him"],["وَجَـٰدَلُوا۟","and they disputed"],["بِٱلْبَـٰطِلِ","by falsehood"],["لِيُدْحِضُوا۟","to refute"],["بِهِ","thereby"],["ٱلْحَقَّ","the truth"],["فَأَخَذْتُهُمْ ۖ","So I seized them"],["فَكَيْفَ","Then how"],["كَانَ","was"],["عِقَابِ","My penalty"]]],"4139":["(Dan demikianlah telah pasti berlaku ketetapan azab Rabbmu) sebagaimana yang telah diungkapkan-Nya dalam firman yang lain, yaitu, \"Sesungguhnya akan Aku penuhi neraka Jahanam itu...\" (Q.S. As-Sajdah, 13) (terhadap orang-orang kafir, karena sesungguhnya mereka adalah penghuni neraka) lafal Annahum Ashhaabun Naari merupakan Badal dari lafal Kalimatu Rabbika.",[["وَكَذَٰلِكَ","And thus"],["حَقَّتْ","has been justified"],["كَلِمَتُ","(the) Word"],["رَبِّكَ","(of) your Lord"],["عَلَى","against"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieved"],["أَنَّهُمْ","that they"],["أَصْحَـٰبُ","(are) companions"],["ٱلنَّارِ","(of) the Fire"]]],"4140":["(Malaikat-malaikat yang memikul Arasy) berkedudukan menjadi Mubtada (dan malaikat yang berada di sekelilingnya) diathafkan kepada ayat sebelumnya (bertasbih) menjadi Khabar dari Mubtada (memuji Rabb mereka) artinya, seraya memuji-Nya yaitu mengucapkan kalimat, \"Subhaanallaah Wa Bihamdihi\" (dan mereka beriman kepada-Nya) kepada Allah swt. dengan kalbu mereka, maksudnya, mereka percaya kepada keesaan-Nya (serta memintakan ampun bagi orang-orang yang beriman) seraya mengucapkan, (\"Ya Rabb kami! Rahmat dan ilmu Engkau meliputi segala sesuatu) maksudnya, rahmat-Mu meliputi segala sesuatu, dan ilmu-Mu meliputi segala sesuatu. (Maka berilah ampun kepada orang-orang yang bertobat) dari kemusyrikan (dan mengikuti jalan Engkau) yakni agama Islam (dan peliharalah mereka dari siksa neraka Jahim) yang apinya menyala-nyala.",[["ٱلَّذِينَ","Those who"],["يَحْمِلُونَ","bear"],["ٱلْعَرْشَ","the Throne"],["وَمَنْ","and who"],["حَوْلَهُۥ","(are) around it"],["يُسَبِّحُونَ","glorify"],["بِحَمْدِ","(the) praises"],["رَبِّهِمْ","(of) their Lord"],["وَيُؤْمِنُونَ","and believe"],["بِهِۦ","in Him"],["وَيَسْتَغْفِرُونَ","and ask forgiveness"],["لِلَّذِينَ","for those who"],["ءَامَنُوا۟","believe"],["رَبَّنَا","Our Lord"],["وَسِعْتَ","You encompass"],["كُلَّ","all"],["شَىْءٍۢ","things"],["رَّحْمَةًۭ","(by Your) Mercy"],["وَعِلْمًۭا","and knowledge"],["فَٱغْفِرْ","so forgive"],["لِلَّذِينَ","those who"],["تَابُوا۟","repent"],["وَٱتَّبَعُوا۟","and follow"],["سَبِيلَكَ","Your Way"],["وَقِهِمْ","and save them (from)"],["عَذَابَ","(the) punishment"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"4141":["(Ya Rabb kami! Masukkanlah mereka ke dalam surga Adn) sebagai tempat tinggal mereka (yang telah Engkau janjikan kepada mereka dan orang-orang yang saleh) lafal Man shalaha diathafkan kepada lafal Hum yang terdapat di dalam lafal Wa-adkhilhum atau yang terdapat pada lafal Wa'adtahum (dari bapak-bapak mereka, dan istri-istri mereka, dan keturunan mereka. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["رَبَّنَا","Our Lord"],["وَأَدْخِلْهُمْ","And admit them"],["جَنَّـٰتِ","(to) Gardens"],["عَدْنٍ","(of) Eden"],["ٱلَّتِى","which"],["وَعَدتَّهُمْ","You have promised them"],["وَمَن","and whoever"],["صَلَحَ","(was) righteous"],["مِنْ","among"],["ءَابَآئِهِمْ","their fathers"],["وَأَزْوَٰجِهِمْ","and their spouses"],["وَذُرِّيَّـٰتِهِمْ ۚ","and their offspring"],["إِنَّكَ","Indeed You"],["أَنتَ","You"],["ٱلْعَزِيزُ","(are) the All-Mighty"],["ٱلْحَكِيمُ","the All-Wise"]]],"4142":["(Dan peliharalah mereka dari kejahatan) dari balasan azabnya (Dan orang-orang yang Engkau pelihara dari balasan kejahatan pada hari itu) pada hari kiamat (maka sesungguhnya telah Engkau anugerahkan rahmat kepadanya dan itulah kemenangan yang besar.\")",[["وَقِهِمُ","And protect them"],["ٱلسَّيِّـَٔاتِ ۚ","(from) the evils"],["وَمَن","And whoever"],["تَقِ","you protect"],["ٱلسَّيِّـَٔاتِ","(from) the evils"],["يَوْمَئِذٍۢ","that Day"],["فَقَدْ","then verily"],["رَحِمْتَهُۥ ۚ","You have bestowed mercy on him"],["وَذَٰلِكَ","And that"],["هُوَ","[it]"],["ٱلْفَوْزُ","(is) the success"],["ٱلْعَظِيمُ","the great"]]],"4143":["(Sesungguhnya orang-orang yang kafir diserukan kepada mereka) oleh para malaikat, sedangkan mereka membenci diri mereka sendiri sewaktu mereka dimasukkan ke dalam neraka (\"Sesungguhnya kebencian Allah) kepada kalian (lebih besar daripada kebencian kalian kepada diri kalian sendiri karena kalian diseru) sewaktu di dunia (untuk beriman, lalu kalian kafir.\")",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["يُنَادَوْنَ","will be cried out to them"],["لَمَقْتُ","Certainly Allah's hatred"],["ٱللَّهِ","Certainly Allah's hatred"],["أَكْبَرُ","(was) greater"],["مِن","than"],["مَّقْتِكُمْ","your hatred"],["أَنفُسَكُمْ","(of) yourselves"],["إِذْ","when"],["تُدْعَوْنَ","you were called"],["إِلَى","to"],["ٱلْإِيمَـٰنِ","the faith"],["فَتَكْفُرُونَ","and you disbelieved"]]],"4144":["(Mereka menjawab, \"Ya Rabb kami, Engkau telah mematikan kami dua kali) yakni dua kali mati (dan telah menghidupkan kami dua kali pula) yakni dua kali hidup. Karena sesungguhnya sebelum itu mereka berupa mani, dalam keadaan mati, kemudian mereka dijadikan hidup, lalu mereka dimatikan lagi, lalu mereka dihidupkan lagi pada hari berbangkit (lalu kami mengakui dosa-dosa kami) yaitu dosa keingkaran kami terhadap adanya hari berbangkit. (Maka adakah untuk keluar) dari neraka lalu kembali lagi ke dunia, supaya kami dapat menjalani ketaatan kepada Rabb kami (sesuatu jalan\") yakni jalan keluar, maka jawaban mereka adalah tidak ada.",[["قَالُوا۟","They (will) say"],["رَبَّنَآ","Our Lord"],["أَمَتَّنَا","You gave us death"],["ٱثْنَتَيْنِ","twice"],["وَأَحْيَيْتَنَا","and You gave us life"],["ٱثْنَتَيْنِ","twice"],["فَٱعْتَرَفْنَا","and we confess"],["بِذُنُوبِنَا","our sins"],["فَهَلْ","So is (there)"],["إِلَىٰ","to"],["خُرُوجٍۢ","get out"],["مِّن","any"],["سَبِيلٍۢ","way"]]],"4145":["(Yang demikian itu) maksudnya, azab yang kalian sedang jalani itu (adalah karena) ketika di dunia (kalian kafir apabila Allah saja disembah) artinya, kalian kafir bilamana Dia diesakan. (Dan apabila Allah dipersekutukan) menjadikan sekutu bagi-Nya (kalian percaya) kalian percaya kepada kemusyrikan itu. (Maka putusan) untuk mengazab kalian (adalah pada Allah Yang Maha Tinggi) atas semua makhluk-Nya (lagi Maha Besar) Maha Agung.",[["ذَٰلِكُم","That"],["بِأَنَّهُۥٓ","(is) because"],["إِذَا","when"],["دُعِىَ","Allah was invoked"],["ٱللَّهُ","Allah was invoked"],["وَحْدَهُۥ","Alone"],["كَفَرْتُمْ ۖ","you disbelieved"],["وَإِن","but if"],["يُشْرَكْ","(others) were associated"],["بِهِۦ","with Him"],["تُؤْمِنُوا۟ ۚ","you believed"],["فَٱلْحُكْمُ","So the judgment"],["لِلَّهِ","(is) with Allah"],["ٱلْعَلِىِّ","the Most High"],["ٱلْكَبِيرِ","the Most Great"]]],"4146":["(Dialah yang memperlihatkan kepada kalian tanda-tanda-Nya) yang menunjukkan akan keesaan-Nya (dan menurunkan untuk kalian rezeki dari langit) berupa hujan. (Dan tiadalah mendapat pelajaran) yakni mengambil nasihat (kecuali orang-orang yang kembali kepada Allah) dari kemusyrikan.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["يُرِيكُمْ","shows you"],["ءَايَـٰتِهِۦ","His Signs"],["وَيُنَزِّلُ","and sends down"],["لَكُم","for you"],["مِّنَ","from"],["ٱلسَّمَآءِ","the sky"],["رِزْقًۭا ۚ","provision"],["وَمَا","But (does) not"],["يَتَذَكَّرُ","take heed"],["إِلَّا","except"],["مَن","(one) who"],["يُنِيبُ","turns"]]],"4147":["(Maka serulah Allah) sembahlah Dia (dengan memurnikan ibadah kepada-Nya) artinya, memurnikan agama dari kemusyrikan (meskipun orang-orang kafir tidak menyukainya) sekalipun mereka tidak menyukai keikhlasan kalian kepada-Nya.",[["فَٱدْعُوا۟","So invoke"],["ٱللَّهَ","Allah"],["مُخْلِصِينَ","(being) sincere"],["لَهُ","to Him"],["ٱلدِّينَ","(in) the religion"],["وَلَوْ","even though"],["كَرِهَ","dislike (it)"],["ٱلْكَـٰفِرُونَ","the disbelievers"]]],"4148":["(Dialah Yang Maha Tinggi derajat-Nya) maksudnya, Allah Maha Agung sifat-sifat-Nya, atau Dialah Yang mengangkat derajat orang-orang yang beriman di surga (Yang mempunyai Arasy) Yang menciptakannya (Yang menurunkan Ar-Ruuh) yakni wahyu (dari perintah-Nya) atau firman-nya (kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya, supaya dia memperingatkan) maksudnya, orang yang menerima wahyu itu diperintahkan untuk menyampaikan wahyu-Nya kepada manusia (tentang hari pertemuan) dapat dibaca At-Talaaqi atau At-Talaaqiy dengan memakai huruf Ya. Yakni hari kiamat, karena pada hari itu penduduk langit dan penduduk bumi bertemu, dan bertemu pula antara Yang Disembah dan yang menyembah, sebagaimana dipertemukan pula antara orang yang aniaya dan orang yang dianiaya.",[["رَفِيعُ","Possessor of the Highest Ranks"],["ٱلدَّرَجَـٰتِ","Possessor of the Highest Ranks"],["ذُو","Owner (of) the Throne"],["ٱلْعَرْشِ","Owner (of) the Throne"],["يُلْقِى","He places"],["ٱلرُّوحَ","the inspiration"],["مِنْ","of"],["أَمْرِهِۦ","His Command"],["عَلَىٰ","upon"],["مَن","whom"],["يَشَآءُ","He wills"],["مِنْ","of"],["عِبَادِهِۦ","His slaves"],["لِيُنذِرَ","to warn"],["يَوْمَ","(of the) Day"],["ٱلتَّلَاقِ","(of) the Meeting"]]],"4149":["(Yaitu hari ketika mereka keluar) dari kuburnya masing-masing (tiada suatu pun dari keadaan mereka yang tersembunyi bagi Allah berfirman, \"Kepunyaan siapakah kerajaan pada hari ini?\") Allah sendiri yang mengatakannya, kemudian Dia sendiri pula yang menjawabnya, yaitu, (\"Hanya kepunyaan Allah Yang Maha Esa lagi Maha Mengalahkan\") atas semua makhluk-Nya.",[["يَوْمَ","(The) Day"],["هُم","they"],["بَـٰرِزُونَ ۖ","come forth"],["لَا","not"],["يَخْفَىٰ","is hidden"],["عَلَى","from"],["ٱللَّهِ","Allah"],["مِنْهُمْ","about them"],["شَىْءٌۭ ۚ","anything"],["لِّمَنِ","For whom"],["ٱلْمُلْكُ","(is) the Dominion"],["ٱلْيَوْمَ ۖ","this Day"],["لِلَّهِ","For Allah"],["ٱلْوَٰحِدِ","the One"],["ٱلْقَهَّارِ","the Irresistible"]]],"4150":["(Pada hari ini tiap-tiap jiwa diberi balasan dengan apa yang diusahakannya. Tidak ada yang dirugikan pada hari ini. Sesungguhnya Allah amat cepat hisab-Nya) Dia menghisab semua makhluk hanya dalam waktu setengah hari dunia, demikianlah menurut keterangan hadis.",[["ٱلْيَوْمَ","This Day"],["تُجْزَىٰ","will be recompensed"],["كُلُّ","every"],["نَفْسٍۭ","soul"],["بِمَا","for what"],["كَسَبَتْ ۚ","it earned"],["لَا","No"],["ظُلْمَ","injustice"],["ٱلْيَوْمَ ۚ","today"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَرِيعُ","(is) Swift"],["ٱلْحِسَابِ","(in) Account"]]],"4151":["(Berilah mereka peringatan dengan hari yang dekat) yakni hari kiamat. Berasal dari kata Azifar Rahiilu, artinya, Waktu berangkat telah dekat (yaitu ketika kalbu) menyesak karena dicekam rasa takut (sampai) artinya hingga sesaknya terasa sampai (di kerongkongan dengan menahan kedukaan) penuh dengan kesedihan. Lafal Kaazhimiina ini adalah Hal atau kata keterangan keadaan bagi lafal Al-Quluubu, kemudian dianggap sebagai jamak dengan memakai huruf Ya dan Nun karena diibaratkan kepada para pemiliknya. (Tiada teman-teman yang setia bagi orang-orang yang zalim) maksudnya tiada teman sejawat dan dekat (dan tidak pula mempunyai seorang pemberi syafaat yang diterima syafaatnya) yang dapat diterima syafaatnya; lafal Yuthaa'u sebagai sifat, tidak mengandung pengertian apa-apa, karena pada asalnya tiada syafaat bagi mereka, sebagaimana yang telah diungkapkan oleh firman-Nya yang lain, yaitu, \"Maka kami tidak mempunyai pemberi syafaat seorang pun.\" (Q.S. Asy-Syu'ara, 100). Tetapi kalau lafal Syafii'in, memang mengandung makna, karena ditinjau dari segi dugaan mereka yaitu, bahwasanya mereka memiliki pemberi-pemberi syafaat. Maksudnya, seandainya mereka memberi syafaat, niscaya syafaat mereka tidak akan diterima.",[["وَأَنذِرْهُمْ","And warn them"],["يَوْمَ","(of the) Day"],["ٱلْـَٔازِفَةِ","the Approaching"],["إِذِ","when"],["ٱلْقُلُوبُ","the hearts"],["لَدَى","(are) at"],["ٱلْحَنَاجِرِ","the throats"],["كَـٰظِمِينَ ۚ","choked"],["مَا","Not"],["لِلظَّـٰلِمِينَ","for the wrongdoers"],["مِنْ","any"],["حَمِيمٍۢ","intimate friend"],["وَلَا","and no"],["شَفِيعٍۢ","intercessor"],["يُطَاعُ","(who) is obeyed"]]],"4152":["(Dia mengetahui) Allah mengetahui (mata yang khianat) ketika mencuri pandang melihat hal-hal yang diharamkan (dan apa yang disembunyikan oleh hati) yang tersimpan di dalam kalbu.",[["يَعْلَمُ","He knows"],["خَآئِنَةَ","(the) stealthy glance"],["ٱلْأَعْيُنِ","(the) stealthy glance"],["وَمَا","and what"],["تُخْفِى","conceal"],["ٱلصُّدُورُ","the breasts"]]],"4153":["(Dan Allah menghukum dengan keadilan. Dan sesembahan-sesembahan yang mereka seru) yang mereka sembah (selain Allah) yakni berhala-berhala (tiada dapat menghukum dengan sesuatu apa pun) mana mungkin mereka menjadi sekutu-sekutu Allah? (Sesungguhnya Allah Dialah Yang Maha Mendengar) semua perkataan mereka (lagi Maha Melihat) semua perbuatan mereka.",[["وَٱللَّهُ","And Allah"],["يَقْضِى","judges"],["بِٱلْحَقِّ ۖ","in truth"],["وَٱلَّذِينَ","while those (whom)"],["يَدْعُونَ","they invoke"],["مِن","besides Him"],["دُونِهِۦ","besides Him"],["لَا","not"],["يَقْضُونَ","they judge"],["بِشَىْءٍ ۗ","with anything"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah "],["هُوَ","He"],["ٱلسَّمِيعُ","(is) the All-Hearer"],["ٱلْبَصِيرُ","the All-Seer"]]],"4154":["(Dan apakah mereka tidak mengadakan perjalanan di muka bumi, lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Mereka itu adalah lebih hebat daripada mereka) menurut suatu qiraat lafal Minhum dibaca Minkum, artinya lebih hebat daripada kalian (kekuatannya dan lebih banyak bekas-bekas mereka di muka bumi) seperti bangunan-bangunan dan gedung-gedungnya (maka Allah mengazab mereka) membinasakan mereka (disebabkan dosa-dosa mereka. Dan sekali-kali mereka tidak mempunyai seorang pelindung dari azab Allah) dari siksaan-Nya.",[["۞ أَوَلَمْ","Do not"],["يَسِيرُوا۟","they travel"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَيَنظُرُوا۟","and see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلَّذِينَ","(of) those who"],["كَانُوا۟","were"],["مِن","before them"],["قَبْلِهِمْ ۚ","before them"],["كَانُوا۟","They were"],["هُمْ","[they]"],["أَشَدَّ","superior"],["مِنْهُمْ","to them"],["قُوَّةًۭ","(in) strength"],["وَءَاثَارًۭا","and (in) impressions"],["فِى","in"],["ٱلْأَرْضِ","the land"],["فَأَخَذَهُمُ","but Allah seized them"],["ٱللَّهُ","but Allah seized them"],["بِذُنُوبِهِمْ","for their sins"],["وَمَا","and not"],["كَانَ","was"],["لَهُم","for them"],["مِّنَ","against"],["ٱللَّهِ","Allah"],["مِن","any"],["وَاقٍۢ","protector"]]],"4155":["(Yang demikian itu adalah karena telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti) yakni mukjizat-mukjizat yang tampak (lalu mereka kafir; maka Allah mengazab mereka. Sesungguhnya Dia Maha Kuat lagi Maha Keras hukuman-Nya.)",[["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(was) because [they]"],["كَانَت","used to come to them"],["تَّأْتِيهِمْ","used to come to them"],["رُسُلُهُم","their Messengers"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["فَكَفَرُوا۟","but they disbelieved"],["فَأَخَذَهُمُ","So Allah seized them"],["ٱللَّهُ ۚ","So Allah seized them"],["إِنَّهُۥ","Indeed, He"],["قَوِىٌّۭ","(is) All-Strong"],["شَدِيدُ","severe"],["ٱلْعِقَابِ","(in) punishment"]]],"4156":["(Dan sesungguhnya telah Kami utus Musa dengan membawa ayat-ayat Kami dan keterangan yang nyata) bukti yang jelas dan tampak.",[["وَلَقَدْ","And certainly"],["أَرْسَلْنَا","We sent"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَا","with Our Signs"],["وَسُلْطَـٰنٍۢ","and an authority"],["مُّبِينٍ","clear"]]],"4157":["(Kepada Firaun, Haman dan Qarun; maka mereka berkata,) \"Dia (adalah seorang ahli sihir yang pendusta.\")",[["إِلَىٰ","To"],["فِرْعَوْنَ","Firaun"],["وَهَـٰمَـٰنَ","Haman"],["وَقَـٰرُونَ","and Qarun"],["فَقَالُوا۟","but they said"],["سَـٰحِرٌۭ","A magician"],["كَذَّابٌۭ","a liar"]]],"4158":["(Maka tatkala Musa datang kepada mereka membawa kebenaran) yakni dengan membawa perkara yang hak (dari sisi Kami, mereka berkata, \"Bunuhlah anak-anak orang-orang yang beriman bersama dengan dia dan biarkanlah hidup) yakni biarkanlah tetap hidup (wanita-wanita mereka.\" Dan tipu daya orang-orang kafir itu tak lain hanyalah sia-sia belaka) yakni menjerumuskan mereka sendiri dalam kebinasaan.",[["فَلَمَّا","Then when"],["جَآءَهُم","he brought to them"],["بِٱلْحَقِّ","the truth"],["مِنْ","from"],["عِندِنَا","Us"],["قَالُوا۟","they said"],["ٱقْتُلُوٓا۟","Kill"],["أَبْنَآءَ","(the) sons"],["ٱلَّذِينَ","(of) those who"],["ءَامَنُوا۟","believe"],["مَعَهُۥ","with him"],["وَٱسْتَحْيُوا۟","and let live"],["نِسَآءَهُمْ ۚ","their women"],["وَمَا","And not"],["كَيْدُ","(is the) plot"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"],["إِلَّا","but"],["فِى","in"],["ضَلَـٰلٍۢ","error"]]],"4159":["(Dan berkata Firaun kepada pembesar-pembesarnya, \"Biarkanlah aku membunuh Musa) karena mereka mencegahnya melakukan pembunuhan terhadap Musa (dan hendaklah ia memohon kepada Rabbnya) supaya Dia mencegah niatku yang akan membunuhnya (karena sesungguhnya aku khawatir dia akan menukar agama kalian) mencegah kalian menyembahku, lalu kalian mengikutinya (atau menimbulkan kerusakan di muka bumi\") seperti melakukan pembunuhan dan lain sebagainya. Menurut suatu qiraat lafal Au dibaca Wa. Dan menurut qiraat lainnya dibaca Ay Yazhhara Fil Ardhil Fasaadu.",[["وَقَالَ","And said"],["فِرْعَوْنُ","Firaun"],["ذَرُونِىٓ","Leave me"],["أَقْتُلْ","(so that) I kill"],["مُوسَىٰ","Musa"],["وَلْيَدْعُ","and let him call"],["رَبَّهُۥٓ ۖ","his Lord"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["أَن","that"],["يُبَدِّلَ","he will change"],["دِينَكُمْ","your religion"],["أَوْ","or"],["أَن","that"],["يُظْهِرَ","he may cause to appear"],["فِى","in"],["ٱلْأَرْضِ","the land"],["ٱلْفَسَادَ","the corruption"]]],"4160":["(Dan Musa berkata,) kepada kaumnya sedangkan dia telah mendengar ancaman Firaun tadi (\"Sesungguhnya aku berlindung kepada Rabbku dan Rabb kalian dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari berhisab.\")",[["وَقَالَ","And said"],["مُوسَىٰٓ","Musa"],["إِنِّى","Indeed, I"],["عُذْتُ","[I] seek refuge"],["بِرَبِّى","in my Lord"],["وَرَبِّكُم","and your Lord"],["مِّن","from"],["كُلِّ","every"],["مُتَكَبِّرٍۢ","arrogant one"],["لَّا","not"],["يُؤْمِنُ","who believes"],["بِيَوْمِ","(in the) Day"],["ٱلْحِسَابِ","(of) the Account"]]],"4161":["(Dan berkatalah seorang laki-laki yang beriman di antara keluarga Firaun) menurut suatu pendapat disebutkan, bahwa ia adalah anak paman Firaun atau saudara sepupunya (yang menyembunyikan imannya, \"Apakah kalian akan membunuh seorang laki-laki karena) sebab (dia menyatakan, 'Rabbku ialah Allah' padahal dia telah datang kepada kalian dengan membawa keterangan-keterangan) yakni mukjizat-mukjizat yang jelas (dari Rabb kalian. Dan jika ia seorang pendusta maka dialah yang menanggung dosa-dustanya itu) yakni dia sendirilah yang menanggung akibat dari kedustaannya (dan jika ia seorang yang benar niscaya sebagian bencana yang diancamkannya kepada kalian akan menimpa kalian\") yakni sebagian azab yang diancamkannya kepada kalian akan segera menimpa diri kalian. (Sesungguhnya Allah tidak menunjuki orang-orang yang melampaui batas) yakni orang yang musyrik (lagi pendusta) yang banyak dustanya.",[["وَقَالَ","And said"],["رَجُلٌۭ","a man"],["مُّؤْمِنٌۭ","believing"],["مِّنْ","from"],["ءَالِ","(the) family"],["فِرْعَوْنَ","(of) Firaun"],["يَكْتُمُ","who conceal(ed)"],["إِيمَـٰنَهُۥٓ","his faith"],["أَتَقْتُلُونَ","Will you kill"],["رَجُلًا","a man"],["أَن","because"],["يَقُولَ","he says"],["رَبِّىَ","My Lord"],["ٱللَّهُ","(is) Allah"],["وَقَدْ","and indeed"],["جَآءَكُم","he has brought you"],["بِٱلْبَيِّنَـٰتِ","clear proofs"],["مِن","from"],["رَّبِّكُمْ ۖ","your Lord"],["وَإِن","And if"],["يَكُ","he is"],["كَـٰذِبًۭا","a liar"],["فَعَلَيْهِ","then upon him"],["كَذِبُهُۥ ۖ","(is) his lie"],["وَإِن","and if"],["يَكُ","he is"],["صَادِقًۭا","truthful"],["يُصِبْكُم","(there) will strike you"],["بَعْضُ","some (of)"],["ٱلَّذِى","(that) which"],["يَعِدُكُمْ ۖ","he threatens you"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["مَنْ","(one) who"],["هُوَ","[he]"],["مُسْرِفٌۭ","(is) a transgressor"],["كَذَّابٌۭ","a liar"]]],"4162":["(Hai kaumku! Untuk kalianlah kerajaan pada hari ini dengan berkuasa) artinya, dengan mengalami kemenangan; lafal Zhaahiriina berkedudukan menjadi Hal atau kata keterangan keadaan (di muka bumi) di negeri Mesir. (Siapakah yang akan menolong kita dari azab Allah) dari azab-Nya bila kalian membunuh kekasih-kekasih-Nya (jika azab itu menimpa kita) tiada seorang pun yang dapat menolong kita (Firaun berkata, \"Aku tidak mengemukakan kepada kalian, melainkan apa yang aku pandang baik;) maksudnya, aku tidak memberikan isyarat kepada kalian melainkan apa yang telah aku putuskan itu, yaitu membunuh Musa (dan aku tiada menunjukkan kepada kalian, selain jalan yang benar\") jalan yang mengandung kebenaran.",[["يَـٰقَوْمِ","O my people"],["لَكُمُ","For you"],["ٱلْمُلْكُ","(is) the kingdom"],["ٱلْيَوْمَ","today"],["ظَـٰهِرِينَ","dominant"],["فِى","in"],["ٱلْأَرْضِ","the land"],["فَمَن","but who"],["يَنصُرُنَا","will help us"],["مِنۢ","from"],["بَأْسِ","(the) punishment"],["ٱللَّهِ","(of) Allah"],["إِن","if"],["جَآءَنَا ۚ","it came to us"],["قَالَ","Said"],["فِرْعَوْنُ","Firaun"],["مَآ","Not"],["أُرِيكُمْ","I show you"],["إِلَّا","except"],["مَآ","what"],["أَرَىٰ","I see"],["وَمَآ","and not"],["أَهْدِيكُمْ","I guide you"],["إِلَّا","except"],["سَبِيلَ","(to the) path"],["ٱلرَّشَادِ","the right"]]],"4163":["(Dan orang yang beriman itu berkata, \"Hai kaumku! Sesungguhnya aku khawatir kalian akan ditimpa -bencana- seperti peristiwa kehancuran golongan yang bersekutu) yakni azab yang telah menimpa umat-umat terdahulu, golongan demi golongan.",[["وَقَالَ","And said"],["ٱلَّذِىٓ","(he) who"],["ءَامَنَ","believed"],["يَـٰقَوْمِ","O my people"],["إِنِّىٓ","Indeed I"],["أَخَافُ","[I] fear"],["عَلَيْكُم","for you"],["مِّثْلَ","like"],["يَوْمِ","(the) day"],["ٱلْأَحْزَابِ","(of) the companies"]]],"4164":["(-Yakni- seperti keadaan kaum Nuh, Ad, Tsamud dan orang-orang yang datang sesudah mereka) lafal Mitsli dalam ayat ini merupakan Badal atau pengganti keterangan dari lafal Mitsli yang sebelumnya, yang ada pada ayat di atas. Yakni, seperti pembalasan yang biasa menimpa orang-orang kafir sebelum kalian; mereka ditimpa azab di dunia. (Dan Allah tidak menghendaki berbuat kelaliman terhadap hamba-hamba-Nya.)",[["مِثْلَ","Like"],["دَأْبِ","(the) plight"],["قَوْمِ","(of the) people"],["نُوحٍۢ","(of) Nuh"],["وَعَادٍۢ","and Aad"],["وَثَمُودَ","and Thamud"],["وَٱلَّذِينَ","and those"],["مِنۢ","after them"],["بَعْدِهِمْ ۚ","after them"],["وَمَا","And Allah (does) not"],["ٱللَّهُ","And Allah (does) not"],["يُرِيدُ","want"],["ظُلْمًۭا","injustice"],["لِّلْعِبَادِ","for (His) slaves"]]],"4165":["(Hai kaumku, sesungguhnya aku khawatir terhadap kalian akan siksa hari panggil-memanggil) dapat dibaca At-Tanaadi atau At-Tanaadiy dengan memakai huruf Ya pada akhirnya. Artinya ialah hari kiamat, yang pada hari itu banyak sekali panggil-memanggil antara ahli surga dan ahli neraka; setiap panggilan sesuai dengan apa yang dialami oleh pemanggilnya. Maka panggilan yang mengandung kebahagiaan adalah bagi ahli surga dan panggilan yang mengandung kecelakaan adalah bagi ahli neraka; selain itu masih banyak pula jenis panggilan atau seruan lainnya.",[["وَيَـٰقَوْمِ","And O my people"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["عَلَيْكُمْ","for you"],["يَوْمَ","(the) Day"],["ٱلتَّنَادِ","(of) Calling"]]],"4166":["(Yaitu hari ketika kalian lari berpaling ke belakang) dari tempat hisab untuk dibawa ke neraka (tidak ada bagi kalian dari Allah) yakni dari azab-Nya (seorang pun yang dapat menyelamatkan kalian) yakni yang dapat mencegah azab dari diri kalian (dan siapa yang disesatkan Allah, niscaya tidak ada baginya seorang pun yang akan memberi petunjuk.\")",[["يَوْمَ","A Day"],["تُوَلُّونَ","you will turn back"],["مُدْبِرِينَ","fleeing"],["مَا","not"],["لَكُم","for you"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["مِنْ","any"],["عَاصِمٍۢ ۗ","protector"],["وَمَن","And whoever"],["يُضْلِلِ","Allah lets go astray"],["ٱللَّهُ","Allah lets go astray"],["فَمَا","then not"],["لَهُۥ","for him"],["مِنْ","any"],["هَادٍۢ","guide"]]],"4167":["(Dan sesungguhnya telah datang Yusuf kepada kalian sebelumnya) yakni sebelum Nabi Musa; menurut suatu pendapat ia adalah Yusuf bin Yakub yang usianya dipanjangkan sampai zaman Nabi Musa; atau menurut pendapat yang lain dia adalah Yusuf bin Ibrahim bin Yusuf bin Nabi Yakub (dengan membawa keterangan-keterangan) mukjizat-mukjizat yang tampak jelas (tetapi kalian senantiasa dalam keraguan tentang apa yang dibawanya kepada kalian, sehingga ketika dia meninggal, kalian berkata,) tanpa memakai bukti yang benar lagi (\"Allah tidak akan mengirim seorang rasul pun sesudahnya.\") selagi kalian masih tetap dalam keadaan kafir atau ingkar kepada Nabi Yusuf dan rasul-rasul lainnya. (Demikianlah) maksudnya sebagaimana kalian disesatkan (Allah menyesatkan orang yang melampaui batas) yakni orang yang musyrik (lagi ragu-ragu) artinya, tidak percaya kepada mukjizat-mukjizat yang telah disaksikannya sendiri.",[["وَلَقَدْ","And indeed"],["جَآءَكُمْ","came to you"],["يُوسُفُ","Yusuf"],["مِن","before"],["قَبْلُ","before"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["فَمَا","but not"],["زِلْتُمْ","you ceased"],["فِى","in"],["شَكٍّۢ","doubt"],["مِّمَّا","about what"],["جَآءَكُم","he brought to you"],["بِهِۦ ۖ","[with it]"],["حَتَّىٰٓ","until"],["إِذَا","when"],["هَلَكَ","he died"],["قُلْتُمْ","you said"],["لَن","Never"],["يَبْعَثَ","will Allah raise"],["ٱللَّهُ","will Allah raise"],["مِنۢ","after him"],["بَعْدِهِۦ","after him"],["رَسُولًۭا ۚ","a Messenger"],["كَذَٰلِكَ","Thus"],["يُضِلُّ","Allah lets go astray"],["ٱللَّهُ","Allah lets go astray"],["مَنْ","who"],["هُوَ","[he]"],["مُسْرِفٌۭ","(is) a transgressor"],["مُّرْتَابٌ","a doubter"]]],"4168":["(Orang-orang yang memperdebatkan ayat-ayat Allah) yaitu mukjizat-mukjizatnya; kalimat ayat ini menjadi Mubtada (tanpa alasan) tanpa argumentasi (yang datang kepada mereka. Amat besar) dosa perdebatan mereka itu, lafal Kabura ini menjadi Khabar dari Mubtada (kemurkaan -bagi mereka- di sisi Allah dan di sisi orang-orang yang beriman. Demikianlah) sebagaimana disesatkan-Nya mereka (Allah mengunci mati) artinya, menyesatkan (hati setiap orang yang sombong lagi sewenang-wenang) dapat dibaca Qalbin Mutakabbirin atau Qalbi Mutakabbirin. Manakala kalbu seseorang merasa sombong, maka takaburlah pemiliknya, dan demikian pula sebaliknya. Lafal Kullun menurut dua qiraat di atas menunjukkan makna tiap-tiap orang yang memiliki kalbu yang sesat, jadi bukan ditujukan kepada semua orang.",[["ٱلَّذِينَ","Those who"],["يُجَـٰدِلُونَ","dispute"],["فِىٓ","concerning"],["ءَايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["بِغَيْرِ","without"],["سُلْطَـٰنٍ","any authority"],["أَتَىٰهُمْ ۖ","(having) come to them"],["كَبُرَ","(it) is greatly"],["مَقْتًا","hateful"],["عِندَ","near Allah"],["ٱللَّهِ","near Allah"],["وَعِندَ","and near"],["ٱلَّذِينَ","those"],["ءَامَنُوا۟ ۚ","who believe"],["كَذَٰلِكَ","Thus"],["يَطْبَعُ","Allah sets a seal"],["ٱللَّهُ","Allah sets a seal"],["عَلَىٰ","over"],["كُلِّ","every"],["قَلْبِ","heart"],["مُتَكَبِّرٍۢ","(of) an arrogant"],["جَبَّارٍۢ","tyrant"]]],"4169":["(Dan berkatalah Firaun, \"Hai Haman! Buatkanlah bagiku sebuah bangunan yang tinggi) bangunan pencakar langit (supaya aku sampai ke pintu-pintu.)",[["وَقَالَ","And said"],["فِرْعَوْنُ","Firaun"],["يَـٰهَـٰمَـٰنُ","O Haman"],["ٱبْنِ","Construct"],["لِى","for me"],["صَرْحًۭا","a tower"],["لَّعَلِّىٓ","that I may"],["أَبْلُغُ","reach"],["ٱلْأَسْبَـٰبَ","the ways"]]],"4170":["(Yaitu pintu-pintu langit) maksudnya, jalan-jalan yang menuju ke arahnya (supaya aku dapat melihat) kalau dibaca Rafa', yaitu Fa-aththali'u berarti di'athafkan pada lafal Ablughu, apabila dibaca Fa-aththali'a berarti menjadi Jawab daripada Fi'il Amar, yaitu lafal Ibni (Tuhan Musa dan sesungguhnya aku memandangnya) menganggap Musa (seorang pendusta\") karena ia mengatakan, bahwa ia mempunyai Tuhan selain aku. Firaun mengatakan demikian untuk mengelabui pengikut-pengikutnya. (Demikianlah dijadikan Firaun memandang baik perbuatan yang buruk itu, dan dia dihalangi dari jalan) petunjuk; dapat dibaca Shadda sehingga artinya menjadi, Dan Firaun menghalangi jalan petunjuk dapat pula dibaca Shudda yang artinya telah tertera di atas (dan tipu daya Firaun itu tidak lain hanyalah membawa kerugian) mengakibatkan kerugian.",[["أَسْبَـٰبَ","(The) ways"],["ٱلسَّمَـٰوَٰتِ","(to) the heavens"],["فَأَطَّلِعَ","so I may look"],["إِلَىٰٓ","at"],["إِلَـٰهِ","(the) God"],["مُوسَىٰ","(of) Musa"],["وَإِنِّى","and indeed, I"],["لَأَظُنُّهُۥ","[I] surely think him"],["كَـٰذِبًۭا ۚ","(to be) a liar"],["وَكَذَٰلِكَ","And thus"],["زُيِّنَ","was made fair-seeming"],["لِفِرْعَوْنَ","to Firaun"],["سُوٓءُ","(the) evil"],["عَمَلِهِۦ","(of) his deed"],["وَصُدَّ","and he was averted"],["عَنِ","from"],["ٱلسَّبِيلِ ۚ","the way"],["وَمَا","And not"],["كَيْدُ","(was the) plot"],["فِرْعَوْنَ","(of) Firaun"],["إِلَّا","except"],["فِى","in"],["تَبَابٍۢ","ruin"]]],"4171":["(Orang yang beriman itu berkata, \"Hai kaumku! Ikutilah aku) dapat dibaca Ittabi'uuni atau Ittabi'uuniy tanpa atau dengan Ya Mutakallim (aku akan menunjukkan kepada kalian jalan yang benar) penafsirannya sebagaimana yang telah lalu.",[["وَقَالَ","And said"],["ٱلَّذِىٓ","the one who"],["ءَامَنَ","believed"],["يَـٰقَوْمِ","O my people"],["ٱتَّبِعُونِ","Follow me"],["أَهْدِكُمْ","I will guide you"],["سَبِيلَ","(to the) way"],["ٱلرَّشَادِ","the right"]]],"4172":["(Hai kaumku, sesungguhnya kehidupan dunia ini hanyalah kesenangan -sementara-) kesenangan yang bersifat sementara lenyap (dan sesungguhnya akhirat itulah negeri yang kekal.)",[["يَـٰقَوْمِ","O my people"],["إِنَّمَا","Only"],["هَـٰذِهِ","this"],["ٱلْحَيَوٰةُ","the life"],["ٱلدُّنْيَا","(of) the world"],["مَتَـٰعٌۭ","(is) enjoyment"],["وَإِنَّ","and indeed"],["ٱلْـَٔاخِرَةَ","the Hereafter "],["هِىَ","it"],["دَارُ","(is the) home"],["ٱلْقَرَارِ","(of) settlement"]]],"4173":["(Barang siapa yang mengerjakan perbuatan jahat, maka dia tidak akan dibalas melainkan sebanding dengan kejahatan itu. Dan barang siapa mengerjakan amal yang saleh, baik laki-laki maupun perempuan sedang ia dalam keadaan beriman, maka mereka akan masuk surga) dapat dibaca Yudkhaluuna atau Yadkhuluuna (mereka diberi rezeki di dalamnya tanpa hisab) diberi rezeki yang banyak tanpa perhitungan.",[["مَنْ","Whoever"],["عَمِلَ","does"],["سَيِّئَةًۭ","an evil"],["فَلَا","then not"],["يُجْزَىٰٓ","he will be recompensed"],["إِلَّا","but"],["مِثْلَهَا ۖ","(the) like thereof"],["وَمَنْ","and whoever"],["عَمِلَ","does"],["صَـٰلِحًۭا","righteous (deeds)"],["مِّن","of"],["ذَكَرٍ","male"],["أَوْ","or"],["أُنثَىٰ","female"],["وَهُوَ","while he"],["مُؤْمِنٌۭ","(is) a believer"],["فَأُو۟لَـٰٓئِكَ","then those"],["يَدْخُلُونَ","will enter"],["ٱلْجَنَّةَ","Paradise"],["يُرْزَقُونَ","they will be given provision"],["فِيهَا","in it"],["بِغَيْرِ","without"],["حِسَابٍۢ","account"]]],"4174":["(Hai kaumku bagaimanakah kalian, aku menyeru kalian kepada keselamatan, tetapi kalian menyeru aku ke neraka.)",[["۞ وَيَـٰقَوْمِ","And O my people"],["مَا","What (is)"],["لِىٓ","for me"],["أَدْعُوكُمْ","(that) I call you"],["إِلَى","to"],["ٱلنَّجَوٰةِ","the salvation"],["وَتَدْعُونَنِىٓ","while you call me"],["إِلَى","to"],["ٱلنَّارِ","the Fire"]]],"4175":["(-Kenapa- kalian menyeruku supaya kafir kepada Allah dan mempersekutukan-Nya dengan apa yang tidak kuketahui padahal aku menyeru kalian -beriman- kepada Yang Maha Perkasa) Yang Maha Menang atas semua perkara-Nya (lagi Maha Pengampun?) kepada orang yang bertobat kepada-Nya.",[["تَدْعُونَنِى","You call me"],["لِأَكْفُرَ","that I disbelieve"],["بِٱللَّهِ","in Allah"],["وَأُشْرِكَ","and (to) associate"],["بِهِۦ","with Him"],["مَا","what"],["لَيْسَ","not"],["لِى","for me"],["بِهِۦ","of it"],["عِلْمٌۭ","any knowledge"],["وَأَنَا۠","and I"],["أَدْعُوكُمْ","call you"],["إِلَى","to"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْغَفَّـٰرِ","the Oft-Forgiving"]]],"4176":["(Sudah pasti) yakni pastilah (bahwa apa yang kalian seru supaya aku -beriman- kepadanya) artinya, supaya aku menyembahnya (tidak dapat memperkenankan seruan apa pun) maksudnya, tidak dapat memperkenankan suatu doa pun (baik di dunia maupun di akhirat. Dan sesungguhnya kita kembali) atau kembali kita (kepada Allah dan sesungguhnya orang-orang yang melampaui batas) yakni orang-orang kafir (mereka itulah penghuni neraka.)",[["لَا","No"],["جَرَمَ","doubt"],["أَنَّمَا","that what"],["تَدْعُونَنِىٓ","you call me"],["إِلَيْهِ","to it"],["لَيْسَ","not"],["لَهُۥ","for it"],["دَعْوَةٌۭ","a claim"],["فِى","in"],["ٱلدُّنْيَا","the world"],["وَلَا","and not"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["وَأَنَّ","and that"],["مَرَدَّنَآ","our return"],["إِلَى","(is) to"],["ٱللَّهِ","Allah"],["وَأَنَّ","and that"],["ٱلْمُسْرِفِينَ","the transgressors "],["هُمْ","they"],["أَصْحَـٰبُ","(will be the) companions"],["ٱلنَّارِ","(of) the Fire"]]],"4177":["(Kelak kalian akan ingat) bila kalian menyaksikan azab dengan mata kalian sendiri (kepada apa yang kukatakan kepada kalian. Dan aku menyerahkan urusanku kepada Allah. Sesungguhnya Allah Maha melihat akan hamba-hamba-Nya\") Ia mengatakan demikian ketika mereka mengancamnya jika ia menentang agama mereka.",[["فَسَتَذْكُرُونَ","And you will remember"],["مَآ","what"],["أَقُولُ","I say"],["لَكُمْ ۚ","to you"],["وَأُفَوِّضُ","and I entrust"],["أَمْرِىٓ","my affair"],["إِلَى","to"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["بَصِيرٌۢ","(is) All-Seer"],["بِٱلْعِبَادِ","of (His) slaves"]]],"4178":["(Maka Allah memeliharanya dari kejahatan tipu daya mereka) terhadap dirinya, yaitu mereka merencanakan akan membunuhnya (dan turunlah) menimpa (kepada keluarga Firaun) maksudnya, kepada kaumnya yang mengikutinya (azab yang buruk) yaitu ditenggelamkan.",[["فَوَقَىٰهُ","So Allah protected him"],["ٱللَّهُ","So Allah protected him"],["سَيِّـَٔاتِ","(from the) evils"],["مَا","that"],["مَكَرُوا۟ ۖ","they plotted"],["وَحَاقَ","and enveloped"],["بِـَٔالِ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["سُوٓءُ","(the) worst"],["ٱلْعَذَابِ","punishment"]]],"4179":["Kemudian (neraka ditampakkan kepada mereka) maksudnya, mereka dibakar oleh api neraka (pada pagi dan petang) di setiap pagi dan petang (dan pada hari terjadinya kiamat) dikatakan kepada mereka, (\"Masuklah kalian) hai (Firaun dan kaumnya) menurut suatu qiraat dibaca Adkhiluu yang artinya, Masukkanlah Firaun dan kaumnya. Ini merupakan perintah Allah kepada malaikat-malaikat-Nya (ke dalam azab yang sangat keras\") yakni azab neraka",[["ٱلنَّارُ","The Fire"],["يُعْرَضُونَ","they are exposed"],["عَلَيْهَا","to it"],["غُدُوًّۭا","morning"],["وَعَشِيًّۭا ۖ","and evening"],["وَيَوْمَ","And (the) Day"],["تَقُومُ","(will be) established"],["ٱلسَّاعَةُ","the Hour"],["أَدْخِلُوٓا۟","Cause to enter"],["ءَالَ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["أَشَدَّ","(in the) severest"],["ٱلْعَذَابِ","punishment"]]],"4180":["(Dan) ingatlah (ketika mereka berbantah) yaitu ketika orang-orang kafir saling berbantah-bantahan (dalam neraka, maka orang-orang yang lemah berkata kepada orang-orang yang menyombongkan diri, \"Sesungguhnya kami adalah pengikut-pengikut kalian) lafal Taba'an adalah bentuk jamak dari lafal Taabi'un (maka dapatkah kalian menghindarkan) artinya menolak (dari kami sebagian) yakni suatu bagian dari (azab api neraka?\")",[["وَإِذْ","And when"],["يَتَحَآجُّونَ","they will dispute"],["فِى","in"],["ٱلنَّارِ","the Fire"],["فَيَقُولُ","then will say"],["ٱلضُّعَفَـٰٓؤُا۟","the weak"],["لِلَّذِينَ","to those who"],["ٱسْتَكْبَرُوٓا۟","were arrogant"],["إِنَّا","Indeed, we"],["كُنَّا","[we] were"],["لَكُمْ","for you"],["تَبَعًۭا","followers"],["فَهَلْ","so can"],["أَنتُم","you"],["مُّغْنُونَ","avert"],["عَنَّا","from us"],["نَصِيبًۭا","a portion"],["مِّنَ","of"],["ٱلنَّارِ","the Fire"]]],"4181":["(Orang-orang yang menyombongkan diri menjawab, \"Sesungguhnya kita semua sama-sama dalam neraka karena sesungguhnya Allah telah menetapkan keputusan antara hamba-hamba-Nya\") oleh karena itu maka Dia memasukkan orang-orang yang beriman ke dalam surga, dan orang-orang kafir ke dalam neraka.",[["قَالَ","Will say"],["ٱلَّذِينَ","those who"],["ٱسْتَكْبَرُوٓا۟","(were) arrogant"],["إِنَّا","Indeed, we"],["كُلٌّۭ","all"],["فِيهَآ","(are) in it"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["قَدْ","certainly"],["حَكَمَ","has judged"],["بَيْنَ","between"],["ٱلْعِبَادِ","(His) slaves"]]],"4182":["(Dan orang-orang yang berada di dalam neraka berkata kepada penjaga-penjaga neraka Jahanam, \"Mohonkanlah kepada Rabb kalian supaya Dia meringankan daripada kami barang sehari) atau selama sehari (dari azab ini.\")",[["وَقَالَ","And will say"],["ٱلَّذِينَ","those"],["فِى","in"],["ٱلنَّارِ","the Fire"],["لِخَزَنَةِ","to (the) keepers"],["جَهَنَّمَ","(of) Hell"],["ٱدْعُوا۟","Call"],["رَبَّكُمْ","your Lord"],["يُخَفِّفْ","(to) lighten"],["عَنَّا","for us"],["يَوْمًۭا","a day"],["مِّنَ","of"],["ٱلْعَذَابِ","the punishment"]]],"4183":["(Para penjaga neraka Jahanam berkata) dengan nada sinis, (\"Dan apakah belum datang kepada kalian rasul-rasul kalian dengan membawa keterangan-keterangan?\") yakni mukjizat-mukjizat yang tampak. (Mereka menjawab, \"Benar, sudah datang\") tetapi mereka kafir kepada rasul-rasul mereka itu. (Penjaga-penjaga Jahanam berkata, \"Berdoalah kalian\") karena sesungguhnya kami tidak akan memberikan syafaat/pertolongan kepada orang-orang kafir. Lalu Allah berfirman, (Tiadalah doa orang-orang kafir itu melainkan sia-sia belaka) yakni tiada gunanya, karena pasti tidak akan diperkenankan.",[["قَالُوٓا۟","They (will) say"],["أَوَلَمْ","Did there not"],["تَكُ","Did there not"],["تَأْتِيكُمْ","come to you"],["رُسُلُكُم","your Messengers"],["بِٱلْبَيِّنَـٰتِ ۖ","with clear proofs"],["قَالُوا۟","They (will) say"],["بَلَىٰ ۚ","Yes"],["قَالُوا۟","They (will) say"],["فَٱدْعُوا۟ ۗ","Then call"],["وَمَا","but not"],["دُعَـٰٓؤُا۟","(is the) call"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"],["إِلَّا","except"],["فِى","in"],["ضَلَـٰلٍ","error"]]],"4184":["(Sesungguhnya Kami menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari berdirinya saksi-saksi) yaitu hari kiamat. Lafal Al-Asyhaad adalah bentuk jamak dari lafal Syaahidun; para saksi tersebut adalah malaikat-malaikat yang memberikan kesaksian bagi para rasul, bahwasanya rasul-rasul itu telah menyampaikan risalah-Nya dan mereka mendustakan orang-orang kafir.",[["إِنَّا","Indeed We"],["لَنَنصُرُ","We will surely help"],["رُسُلَنَا","Our Messengers"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believe"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَيَوْمَ","and (on the) Day"],["يَقُومُ","(when) will stand"],["ٱلْأَشْهَـٰدُ","the witnesses"]]],"4185":["(Yaitu hari yang tidak berguna) dapat dibaca Yanfa'u atau Tanfa'u (bagi orang-orang zalim permintaan maafnya) yakni permintaan maaf mereka seandainya mereka meminta maaf (dan bagi merekalah laknat) yaitu dijauhkan dari rahmat Allah (dan bagi mereka tempat tinggal yang buruk) di akhirat, yaitu mendapat azab yang sangat pedih.",[["يَوْمَ","(The) Day"],["لَا","not"],["يَنفَعُ","will benefit"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["مَعْذِرَتُهُمْ ۖ","their excuse"],["وَلَهُمُ","and for them"],["ٱللَّعْنَةُ","(is) the curse"],["وَلَهُمْ","and for them"],["سُوٓءُ","(is the) worst"],["ٱلدَّارِ","home"]]],"4186":["(Dan sesungguhnya telah Kami berikan petunjuk kepada Musa) berupa kitab Taurat dan mukjizat-mukjizat (dan Kami wariskan kepada Bani Israel) sesudah Musa tiada (kitab) yakni Taurat.",[["وَلَقَدْ","And certainly"],["ءَاتَيْنَا","We gave"],["مُوسَى","Musa"],["ٱلْهُدَىٰ","the guidance"],["وَأَوْرَثْنَا","and We caused to inherit"],["بَنِىٓ","(the) Children of Israel"],["إِسْرَٰٓءِيلَ","(the) Children of Israel"],["ٱلْكِتَـٰبَ","the Book"]]],"4187":["(Untuk menjadi petunjuk) sebagai petunjuk (dan peringatan bagi orang-orang yang berpikir) sebagai peringatan buat orang-orang yang berakal.",[["هُدًۭى","A guide"],["وَذِكْرَىٰ","and a reminder"],["لِأُو۟لِى","for those"],["ٱلْأَلْبَـٰبِ","(of) understanding"]]],"4188":["(Maka bersabarlah kamu) hai Muhammad (karena sesungguhnya janji Allah itu) untuk menolong kekasih-kekasih-Nya (benar) dan kamu beserta orang-orang yang mengikutimu adalah termasuk kekasih-kekasih-Nya (dan mohonlah ampun untuk dosamu) supaya hal ini dijadikan teladan bagi umatmu (dan bertasbihlah) yakni, salatlah seraya (memuji Rabbmu pada waktu petang) yaitu sesudah matahari tergelincir (dan pagi) yang dimaksud adalah salat lima waktu.",[["فَٱصْبِرْ","So be patient"],["إِنَّ","indeed"],["وَعْدَ","(the) Promise of Allah"],["ٱللَّهِ","(the) Promise of Allah"],["حَقٌّۭ","(is) true"],["وَٱسْتَغْفِرْ","And ask forgiveness"],["لِذَنۢبِكَ","for your sin"],["وَسَبِّحْ","and glorify"],["بِحَمْدِ","(the) praise"],["رَبِّكَ","(of) your Lord"],["بِٱلْعَشِىِّ","in the evening"],["وَٱلْإِبْكَـٰرِ","and the morning"]]],"4189":["(Sesungguhnya orang-orang yang memperdebatkan tentang ayat-ayat Allah) yakni Alquran (tanpa alasan) tanpa argumentasi (yang sampai kepada mereka, tidak ada) (dalam dada mereka melainkan hanyalah keinginan akan kebesaran) yakni tinggi diri dan tamak ingin mengatasi kamu (yang mereka sekali-kali tiada akan mencapainya maka mintalah perlindungan) dari kejahatan mereka (kepada Allah. Sesungguhnya Dia Maha Mendengar) akan semua perkataan mereka (lagi Maha Melihat) keadaan mereka; ayat ini diturunkan berkenaan dengan orang-orang yang ingkar kepada hari berbangkit.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يُجَـٰدِلُونَ","dispute"],["فِىٓ","concerning"],["ءَايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["بِغَيْرِ","without"],["سُلْطَـٰنٍ","any authority"],["أَتَىٰهُمْ ۙ","(which) came to them"],["إِن","not"],["فِى","(is) in"],["صُدُورِهِمْ","their breasts"],["إِلَّا","but"],["كِبْرٌۭ","greatness"],["مَّا","not"],["هُم","they"],["بِبَـٰلِغِيهِ ۚ","(can) reach it"],["فَٱسْتَعِذْ","So seek refuge"],["بِٱللَّهِ ۖ","in Allah"],["إِنَّهُۥ","Indeed He"],["هُوَ","He"],["ٱلسَّمِيعُ","(is) the All-Hearer"],["ٱلْبَصِيرُ","the All-Seer"]]],"4190":["(Sesungguhnya penciptaan langit dan bumi) yakni permulaannya (lebih besar daripada penciptaan manusia) untuk yang kedua kalinya, yaitu mengulanginya (tetapi kebanyakan manusia) yakni orang-orang kafir Mekah (tidak mengetahui) hal tersebut, perihal mereka sama dengan orang buta, sedangkan orang yang mengetahui hal tersebut perumpamaannya sama dengan orang yang melihat.",[["لَخَلْقُ","Surely, (the) creation"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["أَكْبَرُ","(is) greater"],["مِنْ","than"],["خَلْقِ","(the) creation"],["ٱلنَّاسِ","(of) the mankind"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"4191":["(Dan tidaklah sama orang yang buta dengan orang yang melihat, dan) tidak sama pula (orang-orang yang beriman serta mengerjakan amal saleh) yaitu orang yang selalu berbuat kebaikan (dengan orang-orang yang durhaka) di dalam lafal ayat ini terdapat tambahan huruf Laa (Sedikit sekali kalian mengambil pelajaran) mengambil nasihat; dapat dibaca Yatadzakkaruuna atau Tatadzakkaruuna, yakni kesadaran mereka terhadap hal ini sangat sedikit.",[["وَمَا","And not"],["يَسْتَوِى","(are) equal"],["ٱلْأَعْمَىٰ","the blind"],["وَٱلْبَصِيرُ","and the seeing"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["وَلَا","and not"],["ٱلْمُسِىٓءُ ۚ","the evildoer"],["قَلِيلًۭا","Little"],["مَّا","(is) what"],["تَتَذَكَّرُونَ","you take heed"]]],"4192":["(Sesungguhnya hari kiamat pasti akan datang, tidak ada keraguan) artinya, tidak diragukan lagi (tentangnya, akan tetapi kebanyakan manusia tidak beriman) kepadanya.",[["إِنَّ","Indeed"],["ٱلسَّاعَةَ","the Hour"],["لَـَٔاتِيَةٌۭ","(is) surely coming"],["لَّا","no"],["رَيْبَ","doubt"],["فِيهَا","in it"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"]]],"4193":["(Dan Rabb kalian berfirman, \"Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagi kalian) maksudnya, sembahlah Aku, niscaya Aku akan memberi pahala kepada kalian. Pengertian ini disimpulkan dari ayat selanjutnya, yaitu, (Sesungguhnya orang-orang yang menyombongkan diri dari menyembah-Ku akan masuk) dapat dibaca Sayadkhuluuna atau Sayudkhaluuna, menurut bacaan yang kedua artinya, mereka akan dimasukkan ke dalam (neraka Jahanam dalam keadaan hina dina\") dalam keadaan terhina.",[["وَقَالَ","And said"],["رَبُّكُمُ","your Lord"],["ٱدْعُونِىٓ","Call upon Me"],["أَسْتَجِبْ","I will respond"],["لَكُمْ ۚ","to you"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَسْتَكْبِرُونَ","(are) proud"],["عَنْ","to"],["عِبَادَتِى","worship Me"],["سَيَدْخُلُونَ","will enter"],["جَهَنَّمَ","Hell"],["دَاخِرِينَ","(in) humiliation"]]],"4194":["(Allahlah yang menjadikan malam untuk kalian supaya kalian beristirahat padanya; dan menjadikan siang terang-benderang) dikaitkannya pengertian melihat kepada siang hanyalah majaz atau kata kiasan belaka, karena pada siang hari manusia dapat melihat. (Sesungguhnya Allah benar-benar mempunyai karunia yang dilimpahkan atas manusia, akan tetapi kebanyakan manusia tidak bersyukur) kepada Allah, malahan mereka tidak beriman kepada-Nya.",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلَّيْلَ","the night"],["لِتَسْكُنُوا۟","that you may rest"],["فِيهِ","in it"],["وَٱلنَّهَارَ","and the day"],["مُبْصِرًا ۚ","giving visibility"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَذُو","(is) Full (of) Bounty"],["فَضْلٍ","(is) Full (of) Bounty"],["عَلَى","to"],["ٱلنَّاسِ","the people"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يَشْكُرُونَ","give thanks"]]],"4195":["(Yang demikian itu adalah Allah, Rabb kalian, Pencipta segala sesuatu, tiada Tuhan melainkan Dia, maka bagaimanakah kalian dapat dipalingkan?) maksudnya, bagaimanakah kalian dipalingkan dari iman kepada-Nya, padahal bukti-bukti-Nya sudah jelas.",[["ذَٰلِكُمُ","That"],["ٱللَّهُ","(is) Allah"],["رَبُّكُمْ","your Lord"],["خَـٰلِقُ","(the) Creator"],["كُلِّ","(of) all"],["شَىْءٍۢ","things"],["لَّآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","Him"],["فَأَنَّىٰ","So how"],["تُؤْفَكُونَ","are you deluded"]]],"4196":["(Seperti demikianlah dipalingkan) artinya sebagaimana mereka dipalingkan, maka dipalingkan pula (orang-orang yang terhadap ayat-ayat Allah) yakni mukjizat-mukjizat-Nya (mereka ingkar.)",[["كَذَٰلِكَ","Thus"],["يُؤْفَكُ","were deluded"],["ٱلَّذِينَ","those who"],["كَانُوا۟","were "],["بِـَٔايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["يَجْحَدُونَ","rejecting"]]],"4197":["(Allahlah yang menjadikan bumi bagi kalian sebagai tempat menetap dan langit sebagai atap) maksudnya, yang menaungi (dan membentuk kalian lalu membaguskan rupa kalian serta memberi kalian rezeki dengan sebagian yang baik-baik. Yang demikian itu adalah Allah Rabb kalian, Maha Agung Allah, Rabb semesta Alam.)",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلْأَرْضَ","the earth"],["قَرَارًۭا","a place of settlement"],["وَٱلسَّمَآءَ","and the sky"],["بِنَآءًۭ","a canopy"],["وَصَوَّرَكُمْ","and He formed you"],["فَأَحْسَنَ","and perfected"],["صُوَرَكُمْ","your forms"],["وَرَزَقَكُم","and provided you"],["مِّنَ","of"],["ٱلطَّيِّبَـٰتِ ۚ","the good things"],["ذَٰلِكُمُ","That"],["ٱللَّهُ","(is) Allah"],["رَبُّكُمْ ۖ","your Lord"],["فَتَبَارَكَ","Then blessed (is)"],["ٱللَّهُ","Allah"],["رَبُّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"4198":["(Dialah Yang hidup kekal tiada Tuhan melainkan Dia, maka serulah Dia) sembahlah Dia (dengan memurnikan ibadah kepada-Nya) dari kemusyrikan. (Segala puji bagi Allah Rabb semesta alam.)",[["هُوَ","He"],["ٱلْحَىُّ","(is) the Ever-Living"],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","but"],["هُوَ","He"],["فَٱدْعُوهُ","so call Him"],["مُخْلِصِينَ","(being) sincere"],["لَهُ","to Him"],["ٱلدِّينَ ۗ","(in) the religion"],["ٱلْحَمْدُ","All praise (be)"],["لِلَّهِ","to Allah"],["رَبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"4199":["(Katakanlah, \"Sesungguhnya aku dilarang menyembah sesembahan yang kalian seru) yang kalian sembah (selain Allah setelah datang kepadaku keterangan-keterangan) yakni bukti-bukti tauhid (dari Rabbku, dan aku diperintahkan supaya tunduk patuh kepada Rabb semesta alam.)",[["۞ قُلْ","Say"],["إِنِّى","Indeed, I"],["نُهِيتُ","[I] have been forbidden"],["أَنْ","to"],["أَعْبُدَ","worship"],["ٱلَّذِينَ","those whom"],["تَدْعُونَ","you call"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["لَمَّا","when"],["جَآءَنِىَ","have come to me"],["ٱلْبَيِّنَـٰتُ","the clear proofs"],["مِن","from"],["رَّبِّى","my Lord"],["وَأُمِرْتُ","and I am commanded"],["أَنْ","to"],["أُسْلِمَ","submit"],["لِرَبِّ","to (the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"4200":["(Dialah Yang menciptakan kalian dari tanah) yang menciptakan bapak moyang kalian yaitu Nabi Adam dari tanah liat (kemudian dari setetes nuthfah) yakni air mani (sesudah itu dari segumpal darah) yakni dari kental (kemudian dikeluarkan-Nya kalian sebagai seorang anak) lafal Thiflan sekalipun bentuknya mufrad atau tunggal, bermakna jamak (kemudian) dibiarkan-Nya kalian hidup (supaya kalian sampai kepada masa dewasa) masa sempurnanya kekuatan kalian, yaitu di antara umur tiga puluh sampai dengan empat puluh tahun (kemudian -dibiarkan-Nya kalian hidup- sampai tua) dapat dibaca Syuyuukhan atau Syiyuukhan (di antara kalian ada yang diwafatkan sebelum itu) sebelum dewasa dan sebelum mencapai usia tua. Dia melakukan hal tersebut kepada kalian supaya kalian hidup (dan supaya kalian sampai pada ajal yang ditentukan) yakni waktu yang telah dibataskan bagi hidup kalian (dan supaya kalian memahami) bukti-bukti yang menunjukkan keesaan-Nya, kemudian kalian beriman kepada-Nya.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["خَلَقَكُم","created you"],["مِّن","from"],["تُرَابٍۢ","dust"],["ثُمَّ","then"],["مِن","from"],["نُّطْفَةٍۢ","a semen-drop"],["ثُمَّ","then"],["مِنْ","from"],["عَلَقَةٍۢ","a clinging substance"],["ثُمَّ","then"],["يُخْرِجُكُمْ","He brings you out"],["طِفْلًۭا","(as) a child"],["ثُمَّ","then"],["لِتَبْلُغُوٓا۟","lets you reach"],["أَشُدَّكُمْ","your maturity"],["ثُمَّ","then"],["لِتَكُونُوا۟","lets you become"],["شُيُوخًۭا ۚ","old "],["وَمِنكُم","and among you"],["مَّن","(is he) who"],["يُتَوَفَّىٰ","dies"],["مِن","before "],["قَبْلُ ۖ","before "],["وَلِتَبْلُغُوٓا۟","and lets you reach"],["أَجَلًۭا","a term"],["مُّسَمًّۭى","specified"],["وَلَعَلَّكُمْ","and that you may"],["تَعْقِلُونَ","use reason"]]],"4201":["(Dialah yang menghidupkan dan yang mematikan, maka apabila Dia menetapkan sesuatu urusan) artinya, Dia berkehendak mewujudkan sesuatu (Dia hanya berkata kepadanya, 'Jadilah!' maka jadilah ia.\") lafal Fayakuunu dapat pula dibaca Fayakuuna akan tetapi dengan memperkirakan adanya huruf An sebelumnya. Yakni, sesuatu yang dikehendaki itu langsung ada sesudah ada kehendak-Nya, sebagaimana yang telah digambarkan oleh makna firman yang tadi itu.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["يُحْىِۦ","gives life"],["وَيُمِيتُ ۖ","and causes death"],["فَإِذَا","And when"],["قَضَىٰٓ","He decrees"],["أَمْرًۭا","a matter"],["فَإِنَّمَا","then only"],["يَقُولُ","He says"],["لَهُۥ","to it"],["كُن","Be"],["فَيَكُونُ","and it is"]]],"4202":["(Apakah kamu tidak melihat kepada orang-orang yang membantah ayat-ayat Allah?) membantah Alquran. (Bagaimanakah) (mereka dapat dipalingkan) dari iman?",[["أَلَمْ","Do not"],["تَرَ","you see"],["إِلَى","[to]"],["ٱلَّذِينَ","those who"],["يُجَـٰدِلُونَ","dispute"],["فِىٓ","concerning"],["ءَايَـٰتِ","(the) Signs"],["ٱللَّهِ","(of) Allah"],["أَنَّىٰ","How"],["يُصْرَفُونَ","they are turned away"]]],"4203":["(Orang-orang yang mendustakan Alkitab) yakni Al-Qur'an (dan wahyu yang dibawa oleh rasul-rasul Kami yang telah Kami utus) dengan membawa ajaran tauhid dan berita tentang adanya hari berbangkit; mereka adalah orang-orang kafir Mekah. (Kelak mereka akan mengetahui) akibat dari kedustaan mereka.",[["ٱلَّذِينَ","Those who"],["كَذَّبُوا۟","deny"],["بِٱلْكِتَـٰبِ","the Book"],["وَبِمَآ","and with what"],["أَرْسَلْنَا","We sent"],["بِهِۦ","with it"],["رُسُلَنَا ۖ","Our Messengers"],["فَسَوْفَ","but soon"],["يَعْلَمُونَ","they will know"]]],"4204":["(Ketika belenggu dipasang di leher mereka) lafal Idz di sini bermakna Idzaa yakni ketika (dan rantai-rantai) pun dipasang pula di leher mereka. Lafal As-Salaasilu ini diathafkan kepada lafal Al-Aghlaalu. Atau berkedudukan menjadi Mubtada sedangkan Khabarnya tidak disebutkan, yaitu lafal Fii Arjulihim. Dengan demikian maka artinya ialah, Dan rantai-rantai pun dipasang pada kaki mereka Atau Khabar lafal As-Salaasilu ini ialah ayat berikutnya, yaitu (seraya mereka diseret) dengannya.",[["إِذِ","When"],["ٱلْأَغْلَـٰلُ","the iron collars"],["فِىٓ","(will be) around"],["أَعْنَـٰقِهِمْ","their necks"],["وَٱلسَّلَـٰسِلُ","and the chains"],["يُسْحَبُونَ","they will be dragged"]]],"4205":["(Ke dalam air yang sangat panas) yakni neraka Jahanam (kemudian mereka dibakar dalam api) maksudnya, mereka dibakar oleh api neraka.",[["فِى","In"],["ٱلْحَمِيمِ","the boiling water"],["ثُمَّ","then"],["فِى","in"],["ٱلنَّارِ","the Fire"],["يُسْجَرُونَ","they will be burned"]]],"4206":["(Kemudian dikatakan kepada mereka) sebagai celaan dan penelanjangan, (\"Manakah berhala-berhala yang selalu kalian persekutukan?)",[["ثُمَّ","Then"],["قِيلَ","it will be said"],["لَهُمْ","to them"],["أَيْنَ","Where"],["مَا","(is) that which"],["كُنتُمْ","you used to"],["تُشْرِكُونَ","associate"]]],"4207":["(Selain Allah?\") yang kalian sembah selain-Nya; yang dimaksud adalah berhala-berhala. (Mereka menjawab, \"Mereka telah hilang lenyap) artinya, telah tiada (dari kami) maka kami tidak melihat mereka (bahkan kami dahulu tiada pernah menyembah sesuatu\") mereka mengingkari penyembahan mereka kepada berhala-berhala itu. Kemudian berhala-berhala sesembahan mereka itu didatangkan, selanjutnya dikatakan kepada mereka, sebagaimana yang disebutkan dalam ayat yang lain, yaitu firman-Nya, \"Sesungguhnya kalian dan apa yang kalian sembah selain Allah, adalah makanan Jahanam.\" (Q.S. Al-Anbiya, 98). (Seperti demikianlah) yakni sebagaimana disesatkan-Nya orang-orang yang mendustakan Alquran (Allah menyesatkan orang-orang kafir.)",[["مِن","Other than"],["دُونِ","Other than"],["ٱللَّهِ ۖ","Allah"],["قَالُوا۟","They will say"],["ضَلُّوا۟","They have departed"],["عَنَّا","from us"],["بَل","Nay"],["لَّمْ","Not"],["نَكُن","we used to"],["نَّدْعُوا۟","[we] call"],["مِن","before"],["قَبْلُ","before"],["شَيْـًۭٔا ۚ","anything"],["كَذَٰلِكَ","Thus"],["يُضِلُّ","Allah lets go astray"],["ٱللَّهُ","Allah lets go astray"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"4208":["Dikatakan pula kepada mereka, (\"Yang demikian itu) yakni azab itu (disebabkan kalian bersuka ria di muka bumi dengan tidak benar) yaitu melakukan perbuatan syirik dan ingkar kepada adanya hari berbangkit (dan karena kalian selalu bersuka ria) artinya, terlalu berlebih-lebihan di dalam bersuka ria.",[["ذَٰلِكُم","That was"],["بِمَا","because"],["كُنتُمْ","you used to"],["تَفْرَحُونَ","rejoice"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بِغَيْرِ","without"],["ٱلْحَقِّ","right"],["وَبِمَا","and because"],["كُنتُمْ","you used to"],["تَمْرَحُونَ","be insolent"]]],"4209":["(Masuklah kalian ke pintu-pintu neraka Jahanam, sedangkan kalian kekal di dalamnya. Maka itulah seburuk-buruk tempat) yakni tempat tinggal (bagi orang-orang yang sombong.\")",[["ٱدْخُلُوٓا۟","Enter"],["أَبْوَٰبَ","(the) gates"],["جَهَنَّمَ","(of) Hell"],["خَـٰلِدِينَ","(to) abide forever"],["فِيهَا ۖ","in it"],["فَبِئْسَ","and wretched is"],["مَثْوَى","(the) abode"],["ٱلْمُتَكَبِّرِينَ","(of) the arrogant"]]],"4210":["(Maka bersabarlah kamu, sesungguhnya janji Allah) yang akan mengazab mereka (adalah benar; maka jika Kami perlihatkan kepadamu) lafal Immaa adalah berasal dari In Syarthiyah yang diidgamkan kepada Maa Zaidah yang berfungsi mengukuhkan makna Syarat di awal Fi'il, kemudian menyusul Nun Taukid sesudahnya yang juga mengukuhkan makna syarath tadi (sebagian siksa yang Kami ancamkan kepada mereka) yakni semasa kamu masih hidup Kami menurunkan sebagian azab kepada mereka. Jawab Syarathnya tidak disebutkan, yaitu lafal Fadzaaka, yakni maka itulah sebagian dari azab Kami (atau pun Kami wafatkan kamu) yaitu sebelum mereka diazab (namun kepada Kami sajalah mereka dikembalikan) lalu Kami akan mengazab mereka dengan siksaan yang sangat keras. Jawab Syarath yang telah disebutkan di atas tadi hanyalah untuk Ma'thuf saja, yakni hanya untuk kalimah, Fa-immaa Nuriyannaka Ba'dhal Ladzii Na'iduhum, Fadzaaka.",[["فَٱصْبِرْ","So be patient"],["إِنَّ","indeed"],["وَعْدَ","(the) Promise"],["ٱللَّهِ","(of) Allah"],["حَقٌّۭ ۚ","(is) true"],["فَإِمَّا","And whether"],["نُرِيَنَّكَ","We show you"],["بَعْضَ","some"],["ٱلَّذِى","(of) what"],["نَعِدُهُمْ","We have promised them"],["أَوْ","or"],["نَتَوَفَّيَنَّكَ","We cause you to die"],["فَإِلَيْنَا","then to Us"],["يُرْجَعُونَ","they will be returned"]]],"4211":["(Dan sesungguhnya telah Kami utus rasul-rasul sebelum kamu; di antara mereka ada yang Kami ceritakan kepadamu dan di antara mereka ada -pula- yang tidak Kami ceritakan kepadamu) menurut suatu riwayat diceritakan, bahwa Allah swt. telah mengutus delapan ribu orang nabi untuk menjadi rasul; yang empat ribu orang di antaranya dari kaum Bani Israel, sedangkan yang empat ribu orang lagi dari kalangan umat-umat selain Bani Israel. (Tidak dapat bagi seorang rasul) di antara rasul-rasul itu (membawa suatu mukjizat, melainkan dengan seizin Allah) karena mereka juga hamba-hamba Allah yang diperintah oleh-Nya (maka apabila telah datang perintah Allah) yang memerintahkan supaya azab diturunkan atas orang-orang kafir (diputuskan) semua perkara di antara rasul-rasul dan orang-orang yang mendustakannya (dengan adil. Dan ketika itu rugilah orang-orang yang berpegang kepada yang batil) yakni, keputusan itu merupakan kemenangan bagi rasul-rasul dan kerugian bagi orang-orang yang mendustakannya; pada hakikatnya sebelum itu pun orang-orang yang mendustakan para rasul sudah merugi.",[["وَلَقَدْ","And certainly"],["أَرْسَلْنَا","We have sent"],["رُسُلًۭا","Messengers"],["مِّن","before you"],["قَبْلِكَ","before you"],["مِنْهُم","Among them"],["مَّن","(are) who "],["قَصَصْنَا","We have related"],["عَلَيْكَ","to you"],["وَمِنْهُم","and among them"],["مَّن","(are) who "],["لَّمْ","not"],["نَقْصُصْ","We have related"],["عَلَيْكَ ۗ","to you"],["وَمَا","And not"],["كَانَ","is"],["لِرَسُولٍ","for any Messenger"],["أَن","that"],["يَأْتِىَ","he brings"],["بِـَٔايَةٍ","a Sign"],["إِلَّا","except"],["بِإِذْنِ","by (the) permission"],["ٱللَّهِ ۚ","(of) Allah"],["فَإِذَا","So when"],["جَآءَ","comes"],["أَمْرُ","(the) Command"],["ٱللَّهِ","(of) Allah"],["قُضِىَ","it will be decided"],["بِٱلْحَقِّ","in truth"],["وَخَسِرَ","and will lose"],["هُنَالِكَ","there"],["ٱلْمُبْطِلُونَ","the falsifiers"]]],"4212":["(Allahlah yang menjadikan binatang ternak untuk kalian) menurut suatu pendapat dikatakan, bahwa yang dimaksud hanyalah unta saja. Tetapi menurut pendapat yang kuat, ternak yang dimaksud mencakup pula sapi dan kambing (sebagiannya untuk kalian kendarai dan sebagiannya untuk kalian makan.)",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلْأَنْعَـٰمَ","the cattle"],["لِتَرْكَبُوا۟","that you may ride"],["مِنْهَا","some of them"],["وَمِنْهَا","and some of them"],["تَأْكُلُونَ","you eat"]]],"4213":["(Dan -ada lagi- manfaat-manfaat lain pada binatang ternak itu untuk kalian) yaitu berupa air susu, keturunan binatang ternak itu dan juga dari bulu-bulunya (dan supaya kalian mencapai suatu keperluan yang tersimpan dalam hati) maksudnya, dapat kalian gunakan untuk mengangkut barang-barang ke berbagai negeri (dengan mengendarainya) di daratan (dan dengan menaiki bahtera) yakni perahu melalui jalan laut (kalian dapat menaiki semuanya.)",[["وَلَكُمْ","And for you"],["فِيهَا","in them"],["مَنَـٰفِعُ","(are) benefits"],["وَلِتَبْلُغُوا۟","and that you may reach"],["عَلَيْهَا","through them"],["حَاجَةًۭ","a need"],["فِى","(that is) in"],["صُدُورِكُمْ","your breasts"],["وَعَلَيْهَا","and upon them"],["وَعَلَى","and upon"],["ٱلْفُلْكِ","the ships"],["تُحْمَلُونَ","you are carried"]]],"4214":["(Dan Dia memperlihatkan kepada kalian tanda-tanda-Nya; maka tanda-tanda Allah yang manakah) yakni tanda-tanda yang menunjukkan kepada keesaan-Nya (yang kalian ingkari?) Istifham atau kata tanya di sini mengandung makna cemoohan. Disebutkan lafal Ayyun dalam bentuk Mudzakkar adalah lebih terkenal daripada bentuk Ta'nitsnya.",[["وَيُرِيكُمْ","And He shows you"],["ءَايَـٰتِهِۦ","His Signs"],["فَأَىَّ","Then which"],["ءَايَـٰتِ","(of the) Signs"],["ٱللَّهِ","(of) Allah"],["تُنكِرُونَ","will you deny"]]],"4215":["(Maka apakah mereka tiada mengadakan perjalanan di muka bumi lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Adalah orang-orang yang sebelum mereka itu lebih hebat kekuatannya dan -lebih banyak- bekas-bekas mereka di muka bumi) seperti gedung-gedung dan bangunan-bangunan lainnya sebagai peninggalan mereka (maka apa yang mereka usahakan itu tidak dapat menolong mereka.)",[["أَفَلَمْ","Do they not"],["يَسِيرُوا۟","travel"],["فِى","through"],["ٱلْأَرْضِ","the land"],["فَيَنظُرُوا۟","and see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلَّذِينَ","(of) those who"],["مِن","(were) before them"],["قَبْلِهِمْ ۚ","(were) before them"],["كَانُوٓا۟","They were"],["أَكْثَرَ","more numerous"],["مِنْهُمْ","than them"],["وَأَشَدَّ","and mightier"],["قُوَّةًۭ","(in) strength"],["وَءَاثَارًۭا","and impressions"],["فِى","in"],["ٱلْأَرْضِ","the land"],["فَمَآ","but not"],["أَغْنَىٰ","availed"],["عَنْهُم","them"],["مَّا","what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"4216":["(Maka tatkala datang kepada mereka rasul-rasul mereka dengan membawa keterangan-keterangan) yakni mukjizat-mukjizat yang nyata (mereka merasa senang) orang-orang kafir itu (dengan apa yang ada pada mereka) yakni rasul-rasul itu (yaitu pengetahuan mereka) pengertian gembira di sini mengandung makna ejekan dan olok-olokan seraya ingkar kepada apa yang didatangkan oleh para rasul itu (dan menimpalah) maksudnya, turunlah (kepada mereka apa yang selalu mereka perolok-olokkan itu) yaitu, azab Allah yang selalu mereka ejek itu.",[["فَلَمَّا","Then when"],["جَآءَتْهُمْ","came to them"],["رُسُلُهُم","their Messengers"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["فَرِحُوا۟","they rejoiced"],["بِمَا","in what"],["عِندَهُم","they had"],["مِّنَ","of"],["ٱلْعِلْمِ","the knowledge"],["وَحَاقَ","and enveloped"],["بِهِم","them"],["مَّا","what"],["كَانُوا۟","they used to"],["بِهِۦ","[at it]"],["يَسْتَهْزِءُونَ","mock"]]],"4217":["(Maka tatkala mereka melihat azab Kami) yakni betapa kerasnya azab Kami (mereka berkata, \"Kami beriman hanya kepada Allah saja, dan kami kafir kepada sesembahan-sesembahan yang telah kami mempersekutukannya dengan Allah.\")",[["فَلَمَّا","So when"],["رَأَوْا۟","they saw"],["بَأْسَنَا","Our punishment"],["قَالُوٓا۟","they said"],["ءَامَنَّا","We believe"],["بِٱللَّهِ","in Allah"],["وَحْدَهُۥ","Alone"],["وَكَفَرْنَا","and we disbelieve"],["بِمَا","in what"],["كُنَّا","we used to"],["بِهِۦ","with Him"],["مُشْرِكِينَ","associate"]]],"4218":["(Maka iman mereka tiada berguna bagi mereka tatkala mereka telah melihat siksa Kami. Itulah sunah Allah) dinashabkannya lafal Sunnatallaahi karena menjadi Mashdar dari Fi'il yang diperkirakan keberadaannya, dan Fi'il tersebut diambil dari lafalnya (yang telah berlaku terhadap hamba-hamba-Nya) yaitu pada semua umat, bahwasanya iman tiada gunanya apabila timbul di kala azab turun. (Dan di waktu itu merugilah orang-orang kafir) yakni jelaslah kerugian mereka; masing-masing di antara mereka mengalami kerugian yang nyata; dan memang sebelum itu pun mereka adalah orang-orang yang merugi.",[["فَلَمْ","But did not"],["يَكُ","But did not"],["يَنفَعُهُمْ","benefit them"],["إِيمَـٰنُهُمْ","their faith"],["لَمَّا","when"],["رَأَوْا۟","they saw"],["بَأْسَنَا ۖ","Our punishment"],["سُنَّتَ","(Such is the) Way"],["ٱللَّهِ","(of) Allah"],["ٱلَّتِى","which"],["قَدْ","(has) indeed"],["خَلَتْ","preceded"],["فِى","among"],["عِبَادِهِۦ ۖ","His slaves"],["وَخَسِرَ","And are lost"],["هُنَالِكَ","there"],["ٱلْكَـٰفِرُونَ","the disbelievers"]]],"4219":["(Haa Miim) hanya Allah saja yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Meem"]]],"4220":["(Diturunkan dari Tuhan Yang Maha Pemurah lagi Maha Penyayang) kalimat ayat ini berkedudukan menjadi Mubtada.",[["تَنزِيلٌۭ","A revelation"],["مِّنَ","from"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["ٱلرَّحِيمِ","the Most Merciful"]]],"4221":["(Kitab) lafal ayat ini menjadi Khabar Mubtada (yang dijelaskan ayat-ayatnya) maksudnya, dijelaskan di dalamnya hukum-hukum, kisah-kisah dan nasihat-nasihat (yakni bacaan dalam bahasa Arab) lafal Qur-aanan berikut sifatnya menjadi Haal atau kata keterangan keadaan dari lafal Kitaabun (untuk kaum) berta'alluq kepada lafal Fushshilat (yang mengetahui) artinya, bagi mereka yang mengerti, yaitu orang-orang Arab.",[["كِتَـٰبٌۭ","A Book"],["فُصِّلَتْ","are detailed"],["ءَايَـٰتُهُۥ","its Verses"],["قُرْءَانًا","a Quran"],["عَرَبِيًّۭا","(in) Arabic"],["لِّقَوْمٍۢ","for a people"],["يَعْلَمُونَ","(who) know"]]],"4222":["(Yang membawa berita gembira) menjadi sifat dari lafal Qur-aanan (dan yang membawa peringatan, tetapi kebanyakan mereka berpaling darinya maka mereka tidak mau mendengarkan) dengan pendengaran yang terdorong oleh perasaan mau menerima apa yang didengarnya.",[["بَشِيرًۭا","A giver of glad tidings"],["وَنَذِيرًۭا","and a warner"],["فَأَعْرَضَ","but turn away"],["أَكْثَرُهُمْ","most of them"],["فَهُمْ","so they"],["لَا","(do) not"],["يَسْمَعُونَ","hear"]]],"4223":["(Mereka berkata) kepada Nabi saw., (\"Hati kami berada dalam tutupan) tertutup dari (apa yang kamu seru kami kepadanya dan di telinga kami ada sumbatan) yakni penutup (dan di antara kami dan kamu ada dinding) pemisah dalam masalah agama (maka bekerjalah kamu) sesuai dengan tuntunan agamamu (sesungguhnya kami bekerja pula\") sesuai dengan tuntunan agama kami.",[["وَقَالُوا۟","And they say"],["قُلُوبُنَا","Our hearts"],["فِىٓ","(are) in"],["أَكِنَّةٍۢ","coverings"],["مِّمَّا","from what"],["تَدْعُونَآ","you call us"],["إِلَيْهِ","to it"],["وَفِىٓ","and in"],["ءَاذَانِنَا","our ears"],["وَقْرٌۭ","(is) deafness"],["وَمِنۢ","and between us"],["بَيْنِنَا","and between us"],["وَبَيْنِكَ","and between you"],["حِجَابٌۭ","(is) a screen"],["فَٱعْمَلْ","So work"],["إِنَّنَا","indeed, we"],["عَـٰمِلُونَ","(are) working"]]],"4224":["(Katakanlah, \"Bahwasanya aku hanyalah seorang manusia seperti kalian, diwahyukan kepadaku bahwasanya Tuhan kalian adalah Tuhan Yang Maha Esa, maka tetaplah pada jalan yang lurus menuju kepada-Nya) yakni dengan beriman dan taat kepada-Nya (dan mohonlah ampun kepada-Nya. Dan kecelakaan yang besarlah) lafal Al-Wail ini merupakan kalimat azab (bagi orang-orang yang musyrik.)",[["قُلْ","Say"],["إِنَّمَآ","Only"],["أَنَا۠","I am"],["بَشَرٌۭ","a man"],["مِّثْلُكُمْ","like you"],["يُوحَىٰٓ","it is revealed"],["إِلَىَّ","to me"],["أَنَّمَآ","that"],["إِلَـٰهُكُمْ","your god"],["إِلَـٰهٌۭ","(is) God"],["وَٰحِدٌۭ","One"],["فَٱسْتَقِيمُوٓا۟","so take a Straight Path"],["إِلَيْهِ","to Him"],["وَٱسْتَغْفِرُوهُ ۗ","and ask His forgiveness"],["وَوَيْلٌۭ","And woe"],["لِّلْمُشْرِكِينَ","to the polytheists"]]],"4225":["(Yaitu orang-orang yang tidak menunaikan zakat dan mereka kepada kehidupan akhirat benar-benar mereka) Hum yang kedua ini mengandung makna mengukuhkan lafal Hum yang pertama (kafir.)",[["ٱلَّذِينَ","Those who"],["لَا","(do) not"],["يُؤْتُونَ","give"],["ٱلزَّكَوٰةَ","the zakah"],["وَهُم","and they"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["هُمْ","they"],["كَـٰفِرُونَ","(are) disbelievers"]]],"4226":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal yang saleh mereka mendapat pahala yang tiada putus-putusnya\") tanpa henti-hentinya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["لَهُمْ","for them"],["أَجْرٌ","(is) a reward"],["غَيْرُ","never ending"],["مَمْنُونٍۢ","never ending"]]],"4227":["(Katakanlah, \"Sesungguhnya patutkah kalian) kedua huruf Hamzah pada lafal A-innakum dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil (kafir kepada Yang menciptakan bumi dalam dua hari) yaitu hari Ahad dan hari Senin (dan kalian adakan sekutu-sekutu bagi-Nya\") tandingan-tandingan bagi-Nya. (Yang bersifat demikian itulah Rabb) yakni pemilik (semesta alam) lafal Al-Aalamiina adalah bentuk jamak dari lafal Aalamun, maksudnya adalah segala sesuatu yang selain Allah. Kemudian dijamakkan mengingat jenisnya yang bermacam-macam, dan jamak di sini memakai Ya dan Nun karena memprioritaskan makhluk yang berakal.",[["۞ قُلْ","Say"],["أَئِنَّكُمْ","Do you indeed"],["لَتَكْفُرُونَ","[surely] disbelieve"],["بِٱلَّذِى","in the One Who"],["خَلَقَ","created"],["ٱلْأَرْضَ","the earth"],["فِى","in"],["يَوْمَيْنِ","two periods"],["وَتَجْعَلُونَ","and you set up"],["لَهُۥٓ","with Him"],["أَندَادًۭا ۚ","rivals"],["ذَٰلِكَ","That"],["رَبُّ","(is the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"4228":["(Dan Dia menjadikan) merupakan jumlah Istinaf, dan tidak boleh di'athafkan kepada Shilah Al-Ladzii karena ada pemisah yang bersifat Ajnabii yaitu ayat, Wataj'aluuna Lahuu Andaadan dan seterusnya (di bumi itu gunung-gunung) yang kokoh dan kuat (di atasnya dan Dia memberkahinya) dengan air yang banyak, dan tanam-tanaman serta pohon-pohon yang banyak pula (dan Dia menentukan) artinya, membagi-bagikan (padanya kadar makanan-makanannya) untuk manusia dan fauna (dalam) masa penjadian yang sempurna yaitu (empat hari) hal ini dijadikan-Nya pada hari Selasa dan Rabu (yang genap) dinashabkan karena menjadi Mashdar, maksudnya penciptaan itu selama empat hari genap; tidak bertambah dan tidak pula berkurang dari itu (bagi orang-orang yang bertanya) maksudnya, sebagai jawaban bagi orang-orang yang menanyakan tentang penciptaan bumi dan segala isinya.",[["وَجَعَلَ","And He placed"],["فِيهَا","therein"],["رَوَٰسِىَ","firmly-set mountains"],["مِن","above it"],["فَوْقِهَا","above it"],["وَبَـٰرَكَ","and He blessed"],["فِيهَا","therein"],["وَقَدَّرَ","and determined"],["فِيهَآ","therein"],["أَقْوَٰتَهَا","its sustenance"],["فِىٓ","in"],["أَرْبَعَةِ","four"],["أَيَّامٍۢ","periods"],["سَوَآءًۭ","equal"],["لِّلسَّآئِلِينَ","for those who ask"]]],"4229":["(Kemudian Dia menuju) bermaksud kepada (penciptaan langit dan langit itu masih merupakan asap) masih berbentuk asap yang membumbung tinggi (lalu Dia berfirman kepadanya dan kepada bumi, \"Datanglah kamu keduanya) menurut perintah-Ku (dengan suka hati atau terpaksa\") kedua lafal ini berkedudukan sama dengan Hal, yakni baik dalam keadaan senang hati atau terpaksa (keduanya menjawab, \"Kami datang) beserta makhluk yang ada pada kami (dengan suka hati\") di dalam ungkapan ini diprioritaskan Dhamir Mudzakkar lagi Aqil; atau khithab kepada keduanya disamakan dengan jamak.",[["ثُمَّ","Then"],["ٱسْتَوَىٰٓ","He directed (Himself)"],["إِلَى","towards"],["ٱلسَّمَآءِ","the heaven"],["وَهِىَ","while it (was)"],["دُخَانٌۭ","smoke"],["فَقَالَ","and He said"],["لَهَا","to it"],["وَلِلْأَرْضِ","and to the earth"],["ٱئْتِيَا","Come both of you"],["طَوْعًا","willingly"],["أَوْ","or"],["كَرْهًۭا","unwillingly"],["قَالَتَآ","They both said"],["أَتَيْنَا","We come"],["طَآئِعِينَ","willingly"]]],"4230":["(Maka Dia menjadikannya) dhamir yang ada pada lafal ayat ini kembali kepada lafal As-Samaa atau langit, karena memandang dari segi maknanya (tujuh langit dalam dua hari) yakni hari Kamis dan hari Jumat, Dia telah selesai dari menciptakan langit pada saat-saat terakhir dari hari tersebut. Dan pada hari itu juga diciptakan Nabi Adam, oleh karena itu maka di sini tidak dikatakan Fasawwaahunna tetapi Faqadhaahunna. Dan sesuai dengan makna ayat ini yaitu ayat-ayat tentang penciptaan langit dan bumi dalam enam hari (dan Dia mewahyukan pada tiap-tiap langit urusannya) yang telah Dia perintahkan kepada penduduk yang ada di dalamnya, yaitu taat dan beribadah kepada-Nya. (Dan Kami hiasi langit yang dekat dengan pelita-pelita) yakni bintang-bintang yang cemerlang (dan Kami memeliharanya) dinashabkan oleh Fi'ilnya yang keberadaannya diperkirakan, Kami menjaganya dengan meteor-meteor dari setan yang mau mencuri-curi pembicaraan para malaikat. (Demikianlah ketentuan Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) makhluk-Nya.",[["فَقَضَىٰهُنَّ","Then He completed them"],["سَبْعَ","(as) seven"],["سَمَـٰوَاتٍۢ","heavens"],["فِى","in"],["يَوْمَيْنِ","two periods"],["وَأَوْحَىٰ","and He revealed"],["فِى","in"],["كُلِّ","each"],["سَمَآءٍ","heaven"],["أَمْرَهَا ۚ","its affair"],["وَزَيَّنَّا","And We adorned"],["ٱلسَّمَآءَ","the heaven"],["ٱلدُّنْيَا","[the world]"],["بِمَصَـٰبِيحَ","with lamps"],["وَحِفْظًۭا ۚ","and (to) guard"],["ذَٰلِكَ","That"],["تَقْدِيرُ","(is the) Decree"],["ٱلْعَزِيزِ","(of) the All-Mighty"],["ٱلْعَلِيمِ","the All-Knower"]]],"4231":["(Jika mereka berpaling) yaitu orang-orang kafir Mekah dari iman sesudah adanya penjelasan ini (maka katakanlah, \"Aku memperingatkan kalian) aku mempertakuti kalian (dengan petir, seperti petir yang menimpa kaum Ad dan kaum Tsamud) yakni dengan azab yang akan membinasakan kalian sama dengan azab yang membinasakan mereka.",[["فَإِنْ","But if"],["أَعْرَضُوا۟","they turn away"],["فَقُلْ","then say"],["أَنذَرْتُكُمْ","I have warned you"],["صَـٰعِقَةًۭ","(of) a thunderbolt"],["مِّثْلَ","like"],["صَـٰعِقَةِ","(the) thunderbolt"],["عَادٍۢ","(of) Aad"],["وَثَمُودَ","and Thamud"]]],"4232":["(Ketika rasul-rasul datang kepada mereka dari depan dan dari belakang mereka) rasul-rasul itu datang kepada mereka dari arah depan dan dari arah belakang, akan tetapi mereka tetap ingkar dan kafir, sebagaimana yang akan dijelaskan nanti. Dan pengertian pembinasaan ini hanya berlaku pada zamannya saja (\"Janganlah kalian menyembah selain Allah. Mereka menjawab, 'Kalau Rabb kami menghendaki tentu Dia menurunkan) kepada kami (malaikat-malaikat-Nya, maka sesungguhnya kami kepada wahyu yang kalian diutus membawanya) sesuai dengan sangkaan kalian itu (adalah orang-orang yang kafir.'\")",[["إِذْ","When"],["جَآءَتْهُمُ","came to them"],["ٱلرُّسُلُ","the Messengers"],["مِنۢ","from before them"],["بَيْنِ","from before them"],["أَيْدِيهِمْ","from before them"],["وَمِنْ","and from"],["خَلْفِهِمْ","behind them"],["أَلَّا","(saying) \"Do not"],["تَعْبُدُوٓا۟","worship"],["إِلَّا","except"],["ٱللَّهَ ۖ","Allah"],["قَالُوا۟","They said"],["لَوْ","If"],["شَآءَ","(had) willed"],["رَبُّنَا","our Lord"],["لَأَنزَلَ","surely, He (would have) sent down"],["مَلَـٰٓئِكَةًۭ","Angels"],["فَإِنَّا","So indeed, we"],["بِمَآ","in what"],["أُرْسِلْتُم","you have been sent"],["بِهِۦ","with"],["كَـٰفِرُونَ","(are) disbelievers"]]],"4233":["(Adapun kaum Ad maka mereka menyombongkan diri di muka bumi tanpa alasan yang benar dan berkata) ketika mereka diperingatkan dengan azab, (\"Siapakah yang lebih besar kekuatannya dari kami?\") maksudnya, tiada seorang pun yang lebih kuat dari kami. Menurut suatu riwayat disebutkan, bahwa seseorang dari mereka mampu mengangkat batu yang sangat besar dari sebuah gunung, kemudian ia mengolahnya sesuai dengan apa yang dia kehendaki. (Dan apakah mereka tidak memperhatikan) apakah mereka tidak mengetahui (bahwa Allah Yang menciptakan mereka adalah lebih besar kekuatan-Nya dari mereka? Dan bahwasanya mereka terhadap tanda-tanda Kami) yakni mukjizat-mukjizat Kami (adalah orang-orang yang ingkar.)",[["فَأَمَّا","Then as for"],["عَادٌۭ","Aad"],["فَٱسْتَكْبَرُوا۟","they were arrogant"],["فِى","in"],["ٱلْأَرْضِ","the land"],["بِغَيْرِ","without"],["ٱلْحَقِّ","[the] right"],["وَقَالُوا۟","and they said"],["مَنْ","Who"],["أَشَدُّ","(is) mightier"],["مِنَّا","than us"],["قُوَّةً ۖ","(in) strength"],["أَوَلَمْ","Do not"],["يَرَوْا۟","they see"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["ٱلَّذِى","the One Who"],["خَلَقَهُمْ","created them"],["هُوَ","He"],["أَشَدُّ","(is) Mightier"],["مِنْهُمْ","than them"],["قُوَّةًۭ ۖ","(in) strength"],["وَكَانُوا۟","But they used to"],["بِـَٔايَـٰتِنَا","in Our Signs"],["يَجْحَدُونَ","deny"]]],"4234":["(Maka Kami meniupkan angin yang amat gemuruh kepada mereka) yakni angin dingin yang sangat keras suaranya, tetapi tanpa hujan (dalam beberapa hari yang sial) dapat dibaca Nahisaatin atau Nahsaatin, artinya hari-hari yang penuh dengan kesialan bagi mereka (karena Kami hendak merasakan kepada mereka itu siksaan yang menghinakan) azab yang menghinakan (dalam kehidupan dunia. Dan sesungguhnya siksaan akhirat lebih menghinakan) lebih keras penghinaannya (sedangkan mereka tidak diberi pertolongan) yang dapat mencegah azab dari diri mereka.",[["فَأَرْسَلْنَا","So We sent"],["عَلَيْهِمْ","upon them"],["رِيحًۭا","a wind"],["صَرْصَرًۭا","furious"],["فِىٓ","in"],["أَيَّامٍۢ","(the) days"],["نَّحِسَاتٍۢ","(of) misfortune"],["لِّنُذِيقَهُمْ","that We may make them taste"],["عَذَابَ","(the) punishment"],["ٱلْخِزْىِ","(of) disgrace"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا ۖ","(of) the world"],["وَلَعَذَابُ","And surely, (the) punishment"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["أَخْزَىٰ ۖ","(is) more disgracing"],["وَهُمْ","and they"],["لَا","will not be helped"],["يُنصَرُونَ","will not be helped"]]],"4235":["(Adapun Kaum Tsamud maka mereka telah Kami beri petunjuk) yaitu Kami telah menjelaskan kepada mereka jalan petunjuk (tetapi mereka lebih menyukai buta) artinya, lebih memilih kafir (daripada petunjuk itu, maka mereka disambar petir azab yang menghinakan) mereka dihinakan oleh azab berupa petir (disebabkan apa yang telah mereka kerjakan.)",[["وَأَمَّا","And as for"],["ثَمُودُ","Thamud"],["فَهَدَيْنَـٰهُمْ","We guided them"],["فَٱسْتَحَبُّوا۟","but they preferred"],["ٱلْعَمَىٰ","[the] blindness"],["عَلَى","over"],["ٱلْهُدَىٰ","the guidance"],["فَأَخَذَتْهُمْ","so seized them"],["صَـٰعِقَةُ","a thunderbolt"],["ٱلْعَذَابِ","(of) the punishment"],["ٱلْهُونِ","humiliating"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"4236":["(Dan Kami selamatkan) dari azab itu (orang-orang yang beriman dan mereka adalah orang-orang yang bertakwa.)",[["وَنَجَّيْنَا","And We saved"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَكَانُوا۟","and used to"],["يَتَّقُونَ","fear (Allah)"]]],"4237":["(Dan) ingatlah (hari ketika digiring) dapat dibaca Yuhsyaru atau Nahsyuru (musuh-musuh Allah ke dalam neraka lalu mereka dikumpulkan semuanya) yakni digiring semuanya ke dalam neraka.",[["وَيَوْمَ","And (the) Day"],["يُحْشَرُ","will be gathered"],["أَعْدَآءُ","(the) enemies"],["ٱللَّهِ","(of) Allah"],["إِلَى","to"],["ٱلنَّارِ","the Fire"],["فَهُمْ","then they"],["يُوزَعُونَ","will be assembled in rows"]]],"4238":["(Sehingga apabila) huruf Maa di sini adalah Zaidah atau tambahan (mereka sampai ke neraka, pendengaran, penglihatan dan kulit mereka menjadi saksi terhadap mereka tentang apa yang telah mereka kerjakan.)",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["مَا","when"],["جَآءُوهَا","they come to it"],["شَهِدَ","(will) testify"],["عَلَيْهِمْ","against them"],["سَمْعُهُمْ","their hearing"],["وَأَبْصَـٰرُهُمْ","and their sight"],["وَجُلُودُهُم","and their skins"],["بِمَا","(as) to what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"4239":["(Dan mereka berkata kepada kulit mereka, \"Mengapa kalian menjadi saksi terhadap kami?\" Kulit mereka menjawab, \"Allah yang menjadikan segala sesuatu pandai berkata telah menjadikan kami pandai berkata) yakni segala sesuatu yang dikehendaki-Nya dapat berbicara (dan Dialah Yang menciptakan kalian pada kali yang pertama dan hanya kepada-Nyalah kalian dikembalikan\") menurut suatu pendapat, dikatakan bahwa perkataan ini adalah perkataan kulit. Menurut pendapat yang lain, perkataan ini adalah firman Allah swt. sebagaimana hal yang telah diterangkan sebelumnya, dan hal ini mirip sekali dengannya, yaitu: Bahwasanya Tuhan Yang mampu menciptakan kalian pada kali yang pertama, lalu menghidupkan kalian kembali sesudah mati, Dia mampu pula untuk menjadikan kulit kalian dan anggota tubuh kalian lainnya untuk dapat berbicara.",[["وَقَالُوا۟","And they will say"],["لِجُلُودِهِمْ","to their skins"],["لِمَ","Why do"],["شَهِدتُّمْ","you testify"],["عَلَيْنَا ۖ","against us"],["قَالُوٓا۟","They will say"],["أَنطَقَنَا","Allah made us speak"],["ٱللَّهُ","Allah made us speak"],["ٱلَّذِىٓ","the One Who"],["أَنطَقَ","makes speak"],["كُلَّ","every"],["شَىْءٍۢ","thing"],["وَهُوَ","and He"],["خَلَقَكُمْ","created you"],["أَوَّلَ","(the) first"],["مَرَّةٍۢ","time"],["وَإِلَيْهِ","and to Him"],["تُرْجَعُونَ","you will be returned"]]],"4240":["(Dan kalian sekali-kali tidak dapat bersembunyi) bila kalian berbuat hal-hal yang keji (dari persaksian pendengaran, penglihatan dan kulit kalian terhadap kalian) karena sesungguhnya kalian tidak percaya dengan adanya hari berbangkit (bahkan kalian mengira) sewaktu kalian menyembunyikan diri (bahwa Allah tidak mengetahui kebanyakan dari apa yang kalian kerjakan.)",[["وَمَا","And not"],["كُنتُمْ","you were"],["تَسْتَتِرُونَ","covering yourselves"],["أَن","lest"],["يَشْهَدَ","testify"],["عَلَيْكُمْ","against you"],["سَمْعُكُمْ","your hearing"],["وَلَآ","and not"],["أَبْصَـٰرُكُمْ","your sight"],["وَلَا","and not"],["جُلُودُكُمْ","your skins"],["وَلَـٰكِن","but"],["ظَنَنتُمْ","you assumed"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَعْلَمُ","know"],["كَثِيرًۭا","much"],["مِّمَّا","of what"],["تَعْمَلُونَ","you do"]]],"4241":["(Dan yang demikian itu) menjadi Mubtada (adalah prasangka kalian) menjadi Badal dari lafal Dzaalika (yang kalian sangka terhadap Rabb kalian) menjadi Na`at, sedangkan Khabar Mubtada ialah (akan menghancurkan kalian) akan membinasakan diri kalian sendiri (maka jadilah kalian termasuk orang-orang yang merugi.\")",[["وَذَٰلِكُمْ","And that"],["ظَنُّكُمُ","(was) your assumption"],["ٱلَّذِى","which"],["ظَنَنتُم","you assumed"],["بِرَبِّكُمْ","about your Lord"],["أَرْدَىٰكُمْ","It has ruined you"],["فَأَصْبَحْتُم","and you have become"],["مِّنَ","of"],["ٱلْخَـٰسِرِينَ","the losers"]]],"4242":["(Jika mereka bersabar) menderita azab (maka nerakalah tempat tinggal) tempat kediaman (bagi mereka, dan jika mereka mengemukakan alasan-alasan) maksudnya, jika mereka meminta kerelaan (maka tidaklah mereka termasuk orang-orang yang diterima alasannya) yakni orang-orang yang tidak mendapat kerelaan.",[["فَإِن","Then if"],["يَصْبِرُوا۟","they endure"],["فَٱلنَّارُ","the Fire"],["مَثْوًۭى","(is) an abode"],["لَّهُمْ ۖ","for them"],["وَإِن","and if"],["يَسْتَعْتِبُوا۟","they ask for favor"],["فَمَا","then not"],["هُم","they"],["مِّنَ","(will be) of"],["ٱلْمُعْتَبِينَ","those who receive favor"]]],"4243":["(Dan Kami tetapkan) Kami tentukan (bagi mereka teman-teman) dari kalangan setan-setan (yang menjadikan mereka memandang bagus apa yang ada di hadapan mereka) yaitu perkara duniawi dan memperturutkan nafsu syahwat (dan di belakang mereka) yaitu perkara akhirat, melalui perkataan mereka, bahwa tidak ada yang namanya hari berbangkit dan hari hisab itu (dan tetaplah atas mereka keputusan azab) sebagaimana yang telah diungkapkan oleh ayat yang lain, yaitu firman-Nya, \"Sesungguhnya Aku akan penuhi neraka Jahanam...\" (Q.S. As-Sajdah, 13) (pada) kalangan (umat-umat terdahulu) yang telah dibinasakan (sebelum mereka dari jin dan manusia, sesungguhnya mereka adalah orang- orang yang merugi.)",[["۞ وَقَيَّضْنَا","And We have destined"],["لَهُمْ","for them"],["قُرَنَآءَ","companions"],["فَزَيَّنُوا۟","(who) made fair-seeming"],["لَهُم","to them"],["مَّا","what"],["بَيْنَ","(was) before them"],["أَيْدِيهِمْ","(was) before them"],["وَمَا","and what"],["خَلْفَهُمْ","(was) behind them"],["وَحَقَّ","and (is) justified"],["عَلَيْهِمُ","against them"],["ٱلْقَوْلُ","the Word"],["فِىٓ","among"],["أُمَمٍۢ","nations"],["قَدْ","(that have) passed away"],["خَلَتْ","(that have) passed away"],["مِن","before them"],["قَبْلِهِم","before them"],["مِّنَ","of"],["ٱلْجِنِّ","the jinn"],["وَٱلْإِنسِ ۖ","and the men"],["إِنَّهُمْ","Indeed, they"],["كَانُوا۟","were"],["خَـٰسِرِينَ","losers"]]],"4244":["(Dan orang-orang yang kafir berkata) sewaktu Nabi saw. membaca Alquran, (\"Janganlah kalian mendengar bacaan Alquran ini dan buatlah hiruk-pikuk terhadapnya) yakni buatlah suara gaduh dan hiruk-pikuk untuk mengganggu bacaannya, dan mereka memang membuat hiruk-pikuk bilamana Nabi membaca Alquran (supaya kalian dapat mengalahkan\") bacaannya lalu ia menjadi diam tidak membaca Alquran.",[["وَقَالَ","And said"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لَا","(Do) not"],["تَسْمَعُوا۟","listen"],["لِهَـٰذَا","to this"],["ٱلْقُرْءَانِ","Quran"],["وَٱلْغَوْا۟","and make noise"],["فِيهِ","therein"],["لَعَلَّكُمْ","so that you may"],["تَغْلِبُونَ","overcome"]]],"4245":["Allah swt. berfirman mengisahkan tentang mereka, (Maka sesungguhnya Kami akan merasakan azab yang keras kepada orang-orang kafir dan Kami akan memberi balasan kepada mereka dengan seburuk-buruk pembalasan bagi apa yang telah mereka kerjakan) yakni pembalasan yang paling buruk sebagai imbalan dari perbuatan mereka itu.",[["فَلَنُذِيقَنَّ","But surely We will cause to taste"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["عَذَابًۭا","a punishment"],["شَدِيدًۭا","severe"],["وَلَنَجْزِيَنَّهُمْ","and surely We will recompense them"],["أَسْوَأَ","(the) worst"],["ٱلَّذِى","(of) what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"4246":["(Demikianlah) azab yang keras itu dan pembalasan yang paling buruk itu (balasan terhadap musuh-musuh Allah) dapat dibaca Jazaa-u A'daaillaahi atau Jazaa-uwa`daaillaahi, yaitu dapat dibaca Tahqiq dan Tas-hil (yaitu neraka) menjadi 'Athaf bayan dari lafal Jazaa-u dan berfungsi menjelaskan maknanya (mereka mendapat tempat tinggal yang kekal di dalamnya) tempat menetap yang tidak akan dipindahkan lagi daripadanya (sebagai pembalasan) dinashabkan karena menjadi Mashdar dari Fi'ilnya yang diperkirakan keberadaannya (dari sikap mereka terhadap ayat-ayat Kami) yakni Alquran (yang mereka ingkari.)",[["ذَٰلِكَ","That"],["جَزَآءُ","(is the) recompense"],["أَعْدَآءِ","(of the) enemies"],["ٱللَّهِ","(of) Allah "],["ٱلنَّارُ ۖ","the Fire"],["لَهُمْ","for them"],["فِيهَا","therein"],["دَارُ","(is the) home"],["ٱلْخُلْدِ ۖ","(of) the eternity"],["جَزَآءًۢ","(as) recompense"],["بِمَا","for what"],["كَانُوا۟","they used to"],["بِـَٔايَـٰتِنَا","of Our Verses"],["يَجْحَدُونَ","reject"]]],"4247":["(Dan orang-orang kafir berkata) sedang mereka di dalam neraka, (\"Ya Rabb kami! Perlihatkanlah kepada kami dua jenis makhluk yang telah menyesatkan kami yaitu sebagian dari jin dan manusia) yakni iblis dan Qabil yang keduanya adalah orang pertama yang mengerjakan kekafiran dan pembunuhan (agar kami letakkan keduanya di bawah telapak kaki kami) dalam neraka (supaya kedua jenis itu menjadi orang-orang yang paling bawah\") di neraka, artinya, azabnya lebih hebat daripada kami.",[["وَقَالَ","And (will) say"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["رَبَّنَآ","Our Lord"],["أَرِنَا","Show us"],["ٱلَّذَيْنِ","those who"],["أَضَلَّانَا","misled us"],["مِنَ","of"],["ٱلْجِنِّ","the jinn"],["وَٱلْإِنسِ","and the men"],["نَجْعَلْهُمَا","(so) we may put them"],["تَحْتَ","under"],["أَقْدَامِنَا","our feet"],["لِيَكُونَا","that they be"],["مِنَ","of"],["ٱلْأَسْفَلِينَ","the lowest"]]],"4248":["(Sesungguhnya orang-orang yang mengatakan, \"Rabb kami adalah Allah,\" kemudian mereka meneguhkan pendirian mereka) dalam ajaran tauhid dan lain-lainnya yang diwajibkan atas mereka (maka malaikat akan turun kepada mereka) sewaktu mereka mati (\"Hendaknya kalian jangan merasa takut) akan mati dan hal-hal yang sesudahnya (dan jangan pula kalian merasa sedih) atas semua yang telah kalian tinggalkan, yaitu istri dan anak-anak, maka Kamilah yang akan menggantikan kedudukan mereka di sisi kalian (dan bergembiralah dengan surga yang telah dijanjikan Allah kepada kalian.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["قَالُوا۟","say"],["رَبُّنَا","Our Lord"],["ٱللَّهُ","(is) Allah"],["ثُمَّ","then"],["ٱسْتَقَـٰمُوا۟","stand firm "],["تَتَنَزَّلُ","will descend"],["عَلَيْهِمُ","on them"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["أَلَّا","(Do) not"],["تَخَافُوا۟","fear"],["وَلَا","and (do) not"],["تَحْزَنُوا۟","grieve"],["وَأَبْشِرُوا۟","but receive the glad tidings"],["بِٱلْجَنَّةِ","of Paradise"],["ٱلَّتِى","which"],["كُنتُمْ","you were"],["تُوعَدُونَ","promised"]]],"4249":["(Kamilah pelindung-pelindung kalian dalam kehidupan dunia) artinya, Kami memelihara kalian di dalamnya (dan di akhirat) maksudnya, Kami akan selalu bersama kalian di akhirat hingga kalian masuk surga (di dalamnya kalian memperoleh apa yang kalian inginkan dan memperoleh pula di dalamnya apa yang kalian minta) berupa semua kenikmatan yang kalian minta.",[["نَحْنُ","We"],["أَوْلِيَآؤُكُمْ","(are) your protectors"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَفِى","and in"],["ٱلْـَٔاخِرَةِ ۖ","the Hereafter"],["وَلَكُمْ","And for you"],["فِيهَا","therein"],["مَا","whatever"],["تَشْتَهِىٓ","desire"],["أَنفُسُكُمْ","your souls"],["وَلَكُمْ","and for you"],["فِيهَا","therein"],["مَا","what"],["تَدَّعُونَ","you ask"]]],"4250":["(Sebagai hidangan) sebagai rezeki yang telah dipersiapkan bagi kalian; lafal ayat ini dinashabkan oleh lafal Ja'ala yang keberadaannya diperkirakan sebelumnya (dari Rabb Yang Maha Pengampun lagi Maha Penyayang\") yaitu dari Allah swt.",[["نُزُلًۭا","A hospitable gift"],["مِّنْ","from"],["غَفُورٍۢ","(the) Oft-Forgiving"],["رَّحِيمٍۢ","(the) Most Merciful"]]],"4251":["(Siapakah yang lebih baik perkataannya) maksudnya, tiada seorang pun yang lebih baik perkataannya (daripada seorang yang menyeru kepada Allah) yakni mentauhidkan-Nya (mengerjakan amal yang saleh dan berkata, \"Sesungguhnya aku termasuk orang-orang yang berserah diri?\")",[["وَمَنْ","And who"],["أَحْسَنُ","(is) better"],["قَوْلًۭا","(in) speech"],["مِّمَّن","than (one) who"],["دَعَآ","invites"],["إِلَى","to"],["ٱللَّهِ","Allah"],["وَعَمِلَ","and does"],["صَـٰلِحًۭا","righteous (deeds)"],["وَقَالَ","and says"],["إِنَّنِى","Indeed, I am"],["مِنَ","of"],["ٱلْمُسْلِمِينَ","those who submit"]]],"4252":["(Dan tidaklah sama kebaikan dan kejahatan) dalam tingkatan rinciannya, karena sebagian daripada keduanya berada di atas sebagian yang lain. (Tolaklah) kejahatan itu (dengan cara) yakni dengan perbuatan (yang lebih baik) seperti marah, imbangilah dengan sabar, bodoh imbangilah dengan santunan, dan perbuatan jahat imbangilah dengan lapang dada atau pemaaf (maka tiba-tiba orang yang antaramu dan antara dia ada permusuhan seolah-olah menjadi teman yang setia) maka jadilah yang dulunya musuhmu kini menjadi teman sejawat dalam hal saling kasih mengasihi, jika kamu mempunyai sikap seperti tersebut. Lafal Al Ladzii Mubtada, dan Ka-annahu adalah Khabarnya, lafal Idzaa menjadi Zharaf bagi makna Tasybih.",[["وَلَا","And not"],["تَسْتَوِى","(are) equal"],["ٱلْحَسَنَةُ","the good (deed)"],["وَلَا","and"],["ٱلسَّيِّئَةُ ۚ","the evil (deed)"],["ٱدْفَعْ","Repel"],["بِٱلَّتِى","by (that) which"],["هِىَ","[it]"],["أَحْسَنُ","(is) better"],["فَإِذَا","then behold"],["ٱلَّذِى","One who"],["بَيْنَكَ","between you"],["وَبَيْنَهُۥ","and between him"],["عَدَٰوَةٌۭ","(was) enmity"],["كَأَنَّهُۥ","(will become) as if he"],["وَلِىٌّ","(was) a friend"],["حَمِيمٌۭ","intimate"]]],"4253":["(Sifat-sifat yang baik itu tidak dianugerahkan) tidak akan diberikan (melainkan kepada orang-orang yang sabar dan tidak dianugerahkan melainkan kepada orang-orang yang mempunyai keberuntungan) yakni pahala (yang besar.)",[["وَمَا","And not"],["يُلَقَّىٰهَآ","it is granted"],["إِلَّا","except"],["ٱلَّذِينَ","(to) those who"],["صَبَرُوا۟","(are) patient"],["وَمَا","and not"],["يُلَقَّىٰهَآ","it is granted"],["إِلَّا","except"],["ذُو","(to the) owner"],["حَظٍّ","(of) fortune"],["عَظِيمٍۢ","great"]]],"4254":["(Dan jika) lafal Immaa ini pada asalnya terdiri dari In Syarthiyyah dan Maa Zaidah yang kemudian keduanya diidgamkan menjadi satu sehingga jadilah Immaa (setan mengganggumu dengan suatu gangguan) yakni jika setan mengalihkan perhatianmu dari pekerti yang baik kepada pekerti yang buruk (maka mohonlah perlindungan kepada Allah) lafal ayat ini menjadi Jawab Syarat, sedangkan Jawab Amar tidak disebutkan, yakni niscaya Dia akan menolak gangguan setan itu dalam dirimu. (Sesungguhnya Dialah Yang Maha Mendengar) semua percakapan (lagi Maha Mengetahui) semua perbuatan.",[["وَإِمَّا","And if"],["يَنزَغَنَّكَ","whisper comes to you"],["مِنَ","from"],["ٱلشَّيْطَـٰنِ","the Shaitaan"],["نَزْغٌۭ","an evil suggestion"],["فَٱسْتَعِذْ","then seek refuge"],["بِٱللَّهِ ۖ","in Allah"],["إِنَّهُۥ","Indeed, He"],["هُوَ","[He]"],["ٱلسَّمِيعُ","(is) the All-Hearer"],["ٱلْعَلِيمُ","the All-Knower"]]],"4255":["(Dan sebagian dari tanda-tanda kekuasaan-Nya ialah malam, siang, matahari, dan bulan. Janganlah kalian bersujud kepada matahari dan jangan pula kepada bulan, tetapi bersujudlah kepada Allah Yang menciptakannya) yang telah menciptakan keempat tanda-tanda tersebut (jika kalian hanya kepada-Nya saja menyembah.)",[["وَمِنْ","And of"],["ءَايَـٰتِهِ","His Signs"],["ٱلَّيْلُ","(are) the night"],["وَٱلنَّهَارُ","and the day"],["وَٱلشَّمْسُ","and the sun"],["وَٱلْقَمَرُ ۚ","and the moon"],["لَا","(Do) not"],["تَسْجُدُوا۟","prostrate"],["لِلشَّمْسِ","to the sun"],["وَلَا","and not"],["لِلْقَمَرِ","to the moon"],["وَٱسْجُدُوا۟","but prostrate"],["لِلَّهِ","to Allah"],["ٱلَّذِى","the One Who"],["خَلَقَهُنَّ","created them"],["إِن","if"],["كُنتُمْ","you"],["إِيَّاهُ","Him alone"],["تَعْبُدُونَ","worship"]]],"4256":["(Jika mereka menyombongkan diri) tidak mau bersujud atau menyembah kepada Allah semata (maka mereka yang di sisi Rabbmu) yakni malaikat-malaikat (bertasbih) artinya, salat (kepada-Nya di malam dan siang hari, sedangkan mereka tidak jemu-jemu) tidak pernah merasa jemu bertasbih.",[["فَإِنِ","But if"],["ٱسْتَكْبَرُوا۟","they are arrogant"],["فَٱلَّذِينَ","then those who"],["عِندَ","(are) near"],["رَبِّكَ","your Lord"],["يُسَبِّحُونَ","glorify"],["لَهُۥ","Him"],["بِٱلَّيْلِ","by night"],["وَٱلنَّهَارِ","and day"],["وَهُمْ","And they"],["لَا","(do) not"],["يَسْـَٔمُونَ ۩","tire"]]],"4257":["(Dan sebagian dari tanda-tanda kekuasaan-Nya bahwa kamu melihat bumi itu kering tandus) yaitu tidak ada tumbuh-tumbuhan padanya (maka apabila Kami turunkan air di atasnya, niscaya ia bergerak) berubah (dan subur) yakni menjadi subur dan rimbun penuh dengan tetumbuhan. (Sesungguhnya Tuhan Yang menghidupkannya tentu dapat menghidupkan yang mati; sesungguhnya Dia Maha Kuasa atas segala sesuatu.)",[["وَمِنْ","And among"],["ءَايَـٰتِهِۦٓ","His Signs"],["أَنَّكَ","(is) that you"],["تَرَى","see"],["ٱلْأَرْضَ","the earth"],["خَـٰشِعَةًۭ","barren"],["فَإِذَآ","but when"],["أَنزَلْنَا","We send down"],["عَلَيْهَا","upon it"],["ٱلْمَآءَ","water"],["ٱهْتَزَّتْ","it is stirred (to life)"],["وَرَبَتْ ۚ","and grows"],["إِنَّ","Indeed"],["ٱلَّذِىٓ","the One Who"],["أَحْيَاهَا","gives it life"],["لَمُحْىِ","(is) surely the Giver of life"],["ٱلْمَوْتَىٰٓ ۚ","(to) the dead"],["إِنَّهُۥ","Indeed, He"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌ","All-Powerful"]]],"4258":["(Sesungguhnya orang-orang yang mengingkari) diambil dari kata Alhada dan Lahada artinya ingkar (kepada ayat-ayat Kami) yakni Alquran dengan cara mendustakannya (mereka tidak tersembunyi dari Kami) maka pasti Kami akan membalas mereka. (Maka apakah orang-orang yang dilemparkan ke dalam neraka lebih baik ataukah orang-orang yang datang dengan aman sentosa pada hari kiamat? Perbuatlah apa yang kalian kehendaki; sesungguhnya Dia Maha Mengetahui apa yang kalian kerjakan) ayat ini merupakan ancaman bagi mereka.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يُلْحِدُونَ","distort"],["فِىٓ","[in]"],["ءَايَـٰتِنَا","Our Verses"],["لَا","(are) not"],["يَخْفَوْنَ","hidden"],["عَلَيْنَآ ۗ","from Us"],["أَفَمَن","So, is (he) who"],["يُلْقَىٰ","is cast"],["فِى","in"],["ٱلنَّارِ","the Fire"],["خَيْرٌ","better"],["أَم","or"],["مَّن","(he) who"],["يَأْتِىٓ","comes"],["ءَامِنًۭا","secure"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) Resurrection"],["ٱعْمَلُوا۟","Do"],["مَا","what"],["شِئْتُمْ ۖ","you will"],["إِنَّهُۥ","Indeed, He"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["بَصِيرٌ","(is) All-Seer"]]],"4259":["(Sesungguhnya orang-orang yang mengingkari peringatan) Alquran (ketika ia datang kepada mereka) niscaya Kami akan membalas mereka (dan sesungguhnya Alquran itu adalah kitab yang mulia) artinya, perkasa.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["بِٱلذِّكْرِ","in the Reminder"],["لَمَّا","when"],["جَآءَهُمْ ۖ","it comes to them"],["وَإِنَّهُۥ","And indeed, it"],["لَكِتَـٰبٌ","(is) surely a Book"],["عَزِيزٌۭ","mighty"]]],"4260":["(Yang tidak datang kepadanya Alquran kebatilan baik dari depan maupun dari belakangnya) yakni tidak ada suatu kitab pun sebelumnya yang mendustakannya, dan tidak pula sesudahnya (yang diturunkan dari Tuhan Yang Maha Bijaksana lagi Maha Terpuji) Allah Yang Maha Terpuji di dalam semua urusan-Nya.",[["لَّا","Not"],["يَأْتِيهِ","comes to it"],["ٱلْبَـٰطِلُ","the falsehood"],["مِنۢ","from"],["بَيْنِ","before it"],["يَدَيْهِ","before it"],["وَلَا","and not"],["مِنْ","from"],["خَلْفِهِۦ ۖ","behind it"],["تَنزِيلٌۭ","A Revelation"],["مِّنْ","from"],["حَكِيمٍ","(the) All-Wise"],["حَمِيدٍۢ","(the) Praiseworthy"]]],"4261":["(Tidaklah ada yang dikatakan kepadamu itu) yakni kedustaan (kecuali) sebagaimana (apa yang sesungguhnya telah dikatakan kepada rasul-rasul sebelum kamu. Sesungguhnya Rabbmu benar-benar mempunyai ampunan) buat orang-orang yang beriman (dan hukuman yang pedih) bagi orang-orang kafir.",[["مَّا","Not"],["يُقَالُ","is said"],["لَكَ","to you"],["إِلَّا","except"],["مَا","what"],["قَدْ","was said"],["قِيلَ","was said"],["لِلرُّسُلِ","to the Messengers"],["مِن","before you"],["قَبْلِكَ ۚ","before you"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["لَذُو","(is) Possessor"],["مَغْفِرَةٍۢ","(of) forgiveness"],["وَذُو","and Possessor"],["عِقَابٍ","(of) penalty"],["أَلِيمٍۢ","painful"]]],"4262":["(Dan jika Kami jadikan ia) yakni Alquran itu (suatu bacaan dalam bahasa selain bahasa Arab tentu mereka mengatakan, \"Mengapa tidak) kenapa tidak (dijelaskan) diterangkan (ayat-ayatnya?) sehingga kami dapat memahaminya. (Apakah) patut Alquran (dalam bahasa asing sedangkan) nabi (adalah orang Arab) Istifham atau kata tanya di sini mengandung makna ingkar, yakni menunjukkan keingkaran mereka. Dan lafal A'jamiyyun ini dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil. (Katakanlah, \"Alquran ini bagi orang-orang yang beriman adalah petunjuk) dari kesesatan (dan penawar) dari kebodohan. (Dan orang-orang yang tidak beriman pada telinga mereka ada sumbatan) penutup, sehingga mereka tidak dapat mendengar (sedangkan Alquran itu suatu kegelapan bagi mereka) karena itu mereka tidak dapat memahaminya. (Mereka itu adalah seperti orang-orang yang dipanggil dari tempat yang jauh\") karenanya mereka tidak dapat mendengar dan tidak dapat memahami panggilan yang ditujukan kepadanya.",[["وَلَوْ","And if"],["جَعَلْنَـٰهُ","We (had) made it"],["قُرْءَانًا","a Quran"],["أَعْجَمِيًّۭا","(in) a foreign (language)"],["لَّقَالُوا۟","they (would have) said"],["لَوْلَا","Why not"],["فُصِّلَتْ","are explained in detail"],["ءَايَـٰتُهُۥٓ ۖ","its verses"],["ءَا۬عْجَمِىٌّۭ","(Is it) a foreign (language)"],["وَعَرَبِىٌّۭ ۗ","and an Arab"],["قُلْ","Say"],["هُوَ","It (is)"],["لِلَّذِينَ","for those who"],["ءَامَنُوا۟","believe"],["هُدًۭى","a guidance"],["وَشِفَآءٌۭ ۖ","and a healing"],["وَٱلَّذِينَ","And those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["فِىٓ","in"],["ءَاذَانِهِمْ","their ears"],["وَقْرٌۭ","(is) deafness"],["وَهُوَ","and it"],["عَلَيْهِمْ","(is) for them"],["عَمًى ۚ","blindness"],["أُو۟لَـٰٓئِكَ","Those"],["يُنَادَوْنَ","are being called"],["مِن","from"],["مَّكَانٍۭ","a place"],["بَعِيدٍۢ","far"]]],"4263":["(Dan sesungguhnya telah Kami berikan kepada Musa Kitab) yakni Taurat (lalu diperselisihkan tentang Taurat itu) ada yang mempercayainya dan ada pula yang mendustakannya, sama dengan apa yang dialami oleh Alquran. (Kalau tidak ada keputusan yang telah terdahulu dari Rabbmu) yang telah memutuskan untuk menangguhkan hisab dan pembalasan bagi semua makhluk sampai hari kiamat nanti (tentulah telah diputuskan di antara mereka) di dunia ini tentang apa yang mereka perselisihkan itu. (Dan sesungguhnya mereka) yaitu orang-orang yang mendustakan terhadap Alquran (benar-benar dalam keragu-raguan yang membingungkan terhadap Alquran) mereka benar-benar ragu terhadapnya.",[["وَلَقَدْ","And certainly"],["ءَاتَيْنَا","We gave"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","the Book"],["فَٱخْتُلِفَ","but disputes arose"],["فِيهِ ۗ","therein"],["وَلَوْلَا","And had it not been"],["كَلِمَةٌۭ","(for) a word"],["سَبَقَتْ","(that) preceded"],["مِن","from"],["رَّبِّكَ","your Lord"],["لَقُضِىَ","surely, would have been settled"],["بَيْنَهُمْ ۚ","between them"],["وَإِنَّهُمْ","But indeed, they"],["لَفِى","surely (are) in"],["شَكٍّۢ","doubt"],["مِّنْهُ","about it"],["مُرِيبٍۢ","disquieting"]]],"4264":["(Barang siapa yang mengerjakan amal yang saleh maka pahalanya untuk dirinya sendiri) ia beramal untuk dirinya sendiri (dan barang siapa yang berbuat jahat maka dosanya atas dirinya sendiri) bahaya dari perbuatan jahatnya itu kembali kepada dirinya sendiri (dan sekali-kali tidaklah Rabbmu menganiaya hamba-hamba-Nya) Dia bukanlah penganiaya hamba-hamba-Nya sebagaimana yang telah diungkapkan oleh ayat lainnya, yaitu firman-Nya, \"Sesungguhnya Allah tidak menganiaya seorang pun walaupun sebesar dzarrah.\" (Q.S. An-Nisa, 40)",[["مَّنْ","Whoever"],["عَمِلَ","does"],["صَـٰلِحًۭا","righteous deeds"],["فَلِنَفْسِهِۦ ۖ","then it is for his soul"],["وَمَنْ","and whoever"],["أَسَآءَ","does evil"],["فَعَلَيْهَا ۗ","then it is against it"],["وَمَا","And not"],["رَبُّكَ","(is) your Lord"],["بِظَلَّـٰمٍۢ","unjust"],["لِّلْعَبِيدِ","to His slaves"]]]});